CREATE FUNCTION commercial.claim_next_agent_run(worker_id uuid, claimed_at_utc timestamp with time zone, lease_until_utc timestamp with time zone) RETURNS TABLE(tenant_id uuid, run_id uuid, requested_by uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
BEGIN
    RETURN QUERY
    WITH candidate AS (
        SELECT candidate_run.id
        FROM commercial.agent_runs candidate_run
        WHERE (
            candidate_run.status_code = 'QUEUED'
            OR (
                candidate_run.status_code = 'RUNNING'
                AND candidate_run.lease_expires_at_utc < claimed_at_utc
            )
        )
        AND (
            candidate_run.next_attempt_at_utc IS NULL
            OR candidate_run.next_attempt_at_utc <= claimed_at_utc
        )
        ORDER BY candidate_run.created_at_utc, candidate_run.id
        FOR UPDATE SKIP LOCKED
        LIMIT 1
    )
    UPDATE commercial.agent_runs claimed
    SET status_code = 'RUNNING',
        lease_owner = worker_id,
        lease_expires_at_utc = lease_until_utc,
        attempts = claimed.attempts + 1,
        version = claimed.version + 1,
        updated_at_utc = claimed_at_utc
    FROM candidate
    WHERE claimed.id = candidate.id
    RETURNING claimed.tenant_id, claimed.id, claimed.requested_by;
END
$$;
CREATE FUNCTION commercial.claim_next_email_work(p_worker_id uuid, p_lease_seconds integer) RETURNS TABLE(tenant_id uuid, inbound_email_id uuid, owner_user_id uuid, correlation_id uuid, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    now_utc timestamptz := pg_catalog.statement_timestamp();
    candidate_tenant uuid;
    candidate_email uuid;
    candidate_owner uuid;
    new_token uuid := pg_catalog.gen_random_uuid();
BEGIN
    IF p_worker_id IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 600 THEN
        RAISE EXCEPTION 'email worker lease is invalid' USING ERRCODE = '22023';
    END IF;
    SELECT email.tenant_id, email.id, mailbox.owner_user_id
    INTO candidate_tenant, candidate_email, candidate_owner
    FROM commercial.inbound_campaign_emails email
    JOIN commercial.inbound_mailboxes mailbox
      ON mailbox.tenant_id = email.tenant_id AND mailbox.id = email.mailbox_id
    LEFT JOIN commercial.email_proposal_automation_runs run
      ON run.tenant_id = email.tenant_id AND run.inbound_email_id = email.id
    LEFT JOIN commercial.email_worker_claims claim
      ON claim.inbound_email_id = email.id
    WHERE mailbox.is_enabled = TRUE
      AND mailbox.auto_send_enabled = TRUE
      AND (run.id IS NULL OR run.status_code = 'PROCESSING')
      AND (claim.inbound_email_id IS NULL OR
           (claim.dead_lettered_at_utc IS NULL AND
            claim.lease_expires_at_utc <= now_utc AND
            (claim.next_attempt_at_utc IS NULL OR
             claim.next_attempt_at_utc <= now_utc)))
    ORDER BY email.received_at_utc, email.id
    FOR UPDATE OF email SKIP LOCKED
    LIMIT 1;
    IF candidate_email IS NULL THEN RETURN; END IF;
    INSERT INTO commercial.email_worker_claims (
        inbound_email_id, tenant_id, claim_token, worker_id,
        lease_expires_at_utc, next_attempt_at_utc,
        last_failure_code, dead_lettered_at_utc, attempts)
    VALUES (
        candidate_email, candidate_tenant, new_token, p_worker_id,
        now_utc + pg_catalog.make_interval(secs => p_lease_seconds),
        NULL, NULL, NULL, 1)
    ON CONFLICT (inbound_email_id) DO UPDATE
    SET claim_token = new_token,
        worker_id = p_worker_id,
        lease_expires_at_utc = now_utc
            + pg_catalog.make_interval(secs => p_lease_seconds),
        next_attempt_at_utc = NULL,
        last_failure_code = NULL,
        attempts = commercial.email_worker_claims.attempts + 1
    WHERE commercial.email_worker_claims.dead_lettered_at_utc IS NULL
      AND commercial.email_worker_claims.lease_expires_at_utc <= now_utc
      AND (commercial.email_worker_claims.next_attempt_at_utc IS NULL OR
           commercial.email_worker_claims.next_attempt_at_utc <= now_utc);
    IF NOT FOUND THEN RETURN; END IF;
    RETURN QUERY SELECT candidate_tenant, candidate_email, candidate_owner,
        pg_catalog.gen_random_uuid(), new_token;
END;
$$;
CREATE FUNCTION commercial.claim_next_inventory_extraction_attempt(p_worker_id uuid, p_lease_seconds integer, p_max_concurrency integer) RETURNS TABLE(tenant_id uuid, attempt_id uuid, import_id uuid, source_file_version bigint, source_hash text, status_code text, stable_submission_key text, provider_name text, provider_version text, external_task_id text, submitted_at_utc timestamp with time zone, started_at_utc timestamp with time zone, last_polled_at_utc timestamp with time zone, polling_checkpoint text, attempt_number integer, requested_by uuid, command_id uuid, correlation_id uuid, claim_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE
    now_utc timestamptz := pg_catalog.statement_timestamp();
    new_token uuid := pg_catalog.gen_random_uuid();
BEGIN
    IF p_worker_id IS NULL OR p_lease_seconds NOT BETWEEN 30 AND 600 OR
       p_max_concurrency NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION 'inventory extraction dispatch bounds are invalid'
            USING ERRCODE = '22023';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('advertified.inventory-extraction.claim', 0));
    RETURN QUERY
    WITH active AS (
        SELECT count(*) AS value
        FROM commercial.inventory_extraction_attempts item
        WHERE item.extracted_artifact_id IS NULL
          AND (item.status_code IN (
                'SUBMITTING', 'RUNNING', 'FAILED_RETRYABLE')
               OR (item.status_code = 'PENDING'
                   AND item.worker_lease_expires_at_utc > now_utc))
    ), candidate AS (
        SELECT attempt.id
        FROM commercial.inventory_extraction_attempts attempt
        WHERE attempt.status_code IN (
                'PENDING', 'SUBMITTING', 'RUNNING', 'FAILED_RETRYABLE')
          AND attempt.extracted_artifact_id IS NULL
          AND (attempt.worker_lease_expires_at_utc IS NULL OR
               attempt.worker_lease_expires_at_utc <= now_utc)
          AND (attempt.status_code <> 'FAILED_RETRYABLE' OR
               attempt.updated_at_utc <= now_utc - interval '30 seconds')
          AND (attempt.status_code <> 'RUNNING' OR
               attempt.last_polled_at_utc IS NULL OR
               attempt.last_polled_at_utc <= now_utc - interval '10 seconds')
          AND (attempt.status_code <> 'PENDING' OR
               (SELECT value FROM active) < p_max_concurrency)
        ORDER BY CASE attempt.status_code
                    WHEN 'RUNNING' THEN 0
                    WHEN 'FAILED_RETRYABLE' THEN 1
                    WHEN 'SUBMITTING' THEN 2
                    ELSE 3
                 END,
                 attempt.updated_at_utc, attempt.created_at_utc,
                 attempt.attempt_number, attempt.id
        FOR UPDATE SKIP LOCKED LIMIT 1
    )
    UPDATE commercial.inventory_extraction_attempts attempt
    SET worker_id = p_worker_id, worker_lease_token = new_token,
        worker_lease_expires_at_utc = now_utc
            + pg_catalog.make_interval(secs => p_lease_seconds)
    FROM candidate
    WHERE attempt.id = candidate.id
    RETURNING attempt.tenant_id, attempt.id, attempt.import_id,
        attempt.source_file_version, attempt.source_hash::text,
        attempt.status_code::text, attempt.stable_submission_key::text,
        attempt.provider_name::text, attempt.provider_version::text,
        attempt.external_task_id::text, attempt.submitted_at_utc,
        attempt.started_at_utc, attempt.last_polled_at_utc,
        attempt.polling_checkpoint::text, attempt.attempt_number,
        attempt.requested_by, attempt.command_id, attempt.correlation_id,
        attempt.worker_lease_token;
END;
$$;
CREATE FUNCTION commercial.claim_next_outbox_event(p_worker_id uuid, p_lease_seconds integer) RETURNS TABLE(event_id uuid, tenant_id uuid, causation_id uuid, correlation_id uuid, event_type_code text, aggregate_type_code text, aggregate_id uuid, aggregate_version bigint, payload_text text, occurred_at_utc timestamp with time zone, claim_token uuid, attempts integer, lease_expires_at_utc timestamp with time zone, dead_lettered_on_claim boolean, failure_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    tenant_context uuid := commercial.current_tenant_id();
    claimed_at_utc timestamptz := pg_catalog.statement_timestamp();
    lease_until_utc timestamptz;
    candidate_id uuid;
    candidate_attempts integer;
    candidate_lease_expired boolean;
BEGIN
    IF tenant_context IS NULL THEN
        RAISE EXCEPTION 'outbox dispatch requires tenant context'
            USING ERRCODE = '42501';
    END IF;
    IF p_worker_id IS NULL OR p_lease_seconds IS NULL
       OR p_lease_seconds < 5 OR p_lease_seconds > 300 THEN
        RAISE EXCEPTION 'outbox claim timing is invalid' USING ERRCODE = '22023';
    END IF;
    lease_until_utc := claimed_at_utc
        + pg_catalog.make_interval(secs => p_lease_seconds);
    SELECT candidate.event_id, candidate.attempts, candidate.lease_expired
    INTO candidate_id, candidate_attempts, candidate_lease_expired
    FROM commercial.lock_next_outbox_event(
        tenant_context, claimed_at_utc) candidate;
    IF candidate_id IS NULL THEN RETURN; END IF;
    IF candidate_attempts >= 4 THEN
        PERFORM commercial.dead_letter_exhausted_outbox_event(
            candidate_id, tenant_context, claimed_at_utc, candidate_lease_expired);
    ELSE
        PERFORM commercial.install_outbox_claim(
            candidate_id, tenant_context, p_worker_id, claimed_at_utc,
            lease_until_utc, candidate_lease_expired);
    END IF;
    RETURN QUERY SELECT event.id, event.tenant_id, event.causation_id,
        event.correlation_id, event.event_type_code::text,
        event.aggregate_type_code::text, event.aggregate_id,
        event.aggregate_version, event.payload_json::text, event.occurred_at_utc,
        event.claim_token, event.attempts, event.lease_expires_at_utc,
        candidate_attempts >= 4, event.last_failure_code::text
    FROM commercial.outbox_messages event
    WHERE event.id = candidate_id AND event.tenant_id = tenant_context;
END;
$$;
CREATE FUNCTION commercial.complete_email_work(p_claim_token uuid, p_success boolean, p_failure_code text, p_failure_delay_seconds integer, p_max_attempts integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    changed integer;
    current_attempts integer;
    now_utc timestamptz := pg_catalog.statement_timestamp();
BEGIN
    IF p_max_attempts NOT BETWEEN 1 AND 20 THEN
        RAISE EXCEPTION 'email worker attempt limit is invalid' USING ERRCODE = '22023';
    END IF;
    IF p_success THEN
        DELETE FROM commercial.email_worker_claims
        WHERE claim_token = p_claim_token
          AND dead_lettered_at_utc IS NULL
          AND lease_expires_at_utc > now_utc;
        GET DIAGNOSTICS changed = ROW_COUNT;
        RETURN CASE WHEN changed = 1 THEN 'completed' ELSE 'fenced' END;
    END IF;
    IF p_failure_code IS NULL OR
       p_failure_code !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,99}$' OR
       p_failure_delay_seconds NOT BETWEEN 15 AND 900 THEN
        RAISE EXCEPTION 'email worker failure is invalid' USING ERRCODE = '22023';
    END IF;
    SELECT attempts INTO current_attempts
    FROM commercial.email_worker_claims
    WHERE claim_token = p_claim_token
      AND dead_lettered_at_utc IS NULL
      AND lease_expires_at_utc > now_utc
    FOR UPDATE;
    IF current_attempts IS NULL THEN
        RETURN 'fenced';
    END IF;
    IF current_attempts >= p_max_attempts THEN
        UPDATE commercial.email_worker_claims
        SET lease_expires_at_utc = now_utc,
            next_attempt_at_utc = NULL,
            last_failure_code = p_failure_code,
            dead_lettered_at_utc = now_utc
        WHERE claim_token = p_claim_token;
        RETURN 'dead_lettered';
    END IF;
    UPDATE commercial.email_worker_claims
    SET lease_expires_at_utc = now_utc,
        next_attempt_at_utc = now_utc
            + pg_catalog.make_interval(secs => p_failure_delay_seconds),
        last_failure_code = p_failure_code
    WHERE claim_token = p_claim_token;
    RETURN 'retry_scheduled';
END;
$_$;
CREATE FUNCTION commercial.current_tenant_id() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    SELECT NULLIF(
        current_setting('advertified.tenant_id', true),
        ''
    )::uuid
$$;
CREATE FUNCTION commercial.current_user_id() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
    SELECT NULLIF(
        current_setting('advertified.user_id', true),
        ''
    )::uuid
$$;
CREATE FUNCTION commercial.dead_letter_exhausted_outbox_event(p_event_id uuid, p_tenant_id uuid, p_failed_at_utc timestamp with time zone, p_lease_expired boolean) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
    UPDATE commercial.outbox_messages event
    SET last_failure_code = CASE WHEN p_lease_expired
            THEN 'OUTBOX_LEASE_EXPIRED'
            ELSE 'OUTBOX_ATTEMPT_LIMIT_REACHED' END,
        last_failure_at_utc = p_failed_at_utc,
        dead_lettered_at_utc = p_failed_at_utc,
        claim_token = NULL, lease_owner = NULL,
        lease_expires_at_utc = NULL, attempt_started_at_utc = NULL,
        next_attempt_at_utc = NULL
    WHERE event.id = p_event_id AND event.tenant_id = p_tenant_id
$$;
CREATE FUNCTION commercial.delivery_proof_source(requested_campaign_id uuid, requested_booking_id uuid) RETURNS TABLE(buyer_tenant_id uuid, supplier_tenant_id uuid, campaign_id uuid, booking_id uuid, campaign_owner_user_id uuid, campaign_version bigint, flight_start date, flight_end date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT campaign.tenant_id, booking.supplier_tenant_id,
        campaign.id, booking.id, campaign.owner_user_id,
        campaign.version, booking.flight_start, booking.flight_end
    FROM commercial.campaigns campaign
    JOIN commercial.bookings booking
      ON booking.buyer_tenant_id = campaign.tenant_id
     AND booking.proposal_decision_id = campaign.proposal_decision_id
     AND booking.plan_version_id = campaign.plan_version_id
    WHERE campaign.id = requested_campaign_id
      AND booking.id = requested_booking_id
      AND campaign.status_code = 'COMPLETED'
      AND campaign.proof_requested_by IS NOT NULL
      AND campaign.proof_requested_at_utc IS NOT NULL
      AND booking.status_code = 'CONFIRMED'
      AND booking.supplier_tenant_id = commercial.current_tenant_id();
$$;
CREATE FUNCTION commercial.enforce_booking_funding_order() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM commercial.campaigns campaign
        JOIN commercial.payment_intents payment
          ON payment.tenant_id = campaign.tenant_id
         AND payment.id = campaign.payment_intent_id
        WHERE campaign.tenant_id = NEW.buyer_tenant_id
          AND campaign.proposal_decision_id = NEW.proposal_decision_id
          AND campaign.plan_version_id = NEW.plan_version_id
          AND campaign.status_code = 'PLANNED'
          AND payment.status_code = 'CONFIRMED') THEN
        RAISE EXCEPTION 'confirmed funding is required before booking';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_booking_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'booking records cannot be deleted';
    END IF;
    IF (NEW.id, NEW.buyer_tenant_id, NEW.supplier_tenant_id,
        NEW.proposal_version_id, NEW.proposal_option_id,
        NEW.proposal_decision_id, NEW.plan_version_id,
        NEW.media_plan_line_id, NEW.marketplace_listing_version_id,
        NEW.commercial_policy_version_id, NEW.supplier_id,
        NEW.inventory_product_id, NEW.product_version_id,
        NEW.rate_id, NEW.availability_id, NEW.supplier_name,
        NEW.product_name, NEW.channel_code, NEW.geography,
        NEW.flight_start, NEW.flight_end, NEW.running_periods,
        NEW.quantity, NEW.supplier_cost_minor, NEW.markup_minor,
        NEW.commission_minor, NEW.management_fee_minor,
        NEW.client_price_minor, NEW.fees_minor, NEW.vat_minor,
        NEW.booking_approval_threshold_minor,
        NEW.currency_collection_code, NEW.currency_code,
        NEW.terms, NEW.created_by, NEW.created_at_utc)
        IS DISTINCT FROM
       (OLD.id, OLD.buyer_tenant_id, OLD.supplier_tenant_id,
        OLD.proposal_version_id, OLD.proposal_option_id,
        OLD.proposal_decision_id, OLD.plan_version_id,
        OLD.media_plan_line_id, OLD.marketplace_listing_version_id,
        OLD.commercial_policy_version_id, OLD.supplier_id,
        OLD.inventory_product_id, OLD.product_version_id,
        OLD.rate_id, OLD.availability_id, OLD.supplier_name,
        OLD.product_name, OLD.channel_code, OLD.geography,
        OLD.flight_start, OLD.flight_end, OLD.running_periods,
        OLD.quantity, OLD.supplier_cost_minor, OLD.markup_minor,
        OLD.commission_minor, OLD.management_fee_minor,
        OLD.client_price_minor, OLD.fees_minor, OLD.vat_minor,
        OLD.booking_approval_threshold_minor,
        OLD.currency_collection_code, OLD.currency_code,
        OLD.terms, OLD.created_by, OLD.created_at_utc) THEN
        RAISE EXCEPTION 'booking commercial snapshot is immutable';
    END IF;
    IF NEW.version <> OLD.version + 1 OR NEW.updated_at_utc < OLD.updated_at_utc THEN
        RAISE EXCEPTION 'invalid booking version transition';
    END IF;
    IF OLD.status_code = 'DRAFT' AND NEW.status_code = 'PENDING_SUPPLIER' THEN
        IF commercial.current_tenant_id() <> OLD.buyer_tenant_id
           OR NEW.requested_by <> commercial.current_user_id()
           OR NEW.requested_at_utc IS NULL
           OR btrim(COALESCE(NEW.request_reason, '')) = ''
           OR NEW.confirmed_by IS NOT NULL OR NEW.confirmed_at_utc IS NOT NULL
           OR NEW.confirmation_reason IS NOT NULL OR NEW.supplier_note IS NOT NULL
           OR NEW.terms_accepted THEN
            RAISE EXCEPTION 'invalid buyer booking request';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'PENDING_SUPPLIER' AND NEW.status_code = 'CONFIRMED' THEN
        IF commercial.current_tenant_id() <> OLD.supplier_tenant_id
           OR NEW.confirmed_by <> commercial.current_user_id()
           OR NEW.confirmed_at_utc IS NULL
           OR btrim(COALESCE(NEW.confirmation_reason, '')) = ''
           OR NOT NEW.terms_accepted
           OR (NEW.requested_by, NEW.requested_at_utc, NEW.request_reason)
              IS DISTINCT FROM
              (OLD.requested_by, OLD.requested_at_utc, OLD.request_reason) THEN
            RAISE EXCEPTION 'invalid supplier booking confirmation';
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'invalid booking lifecycle transition';
END;
$$;
CREATE FUNCTION commercial.enforce_campaign_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
DECLARE requirement_count integer;
DECLARE booking_count integer;
BEGIN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'campaigns cannot be deleted'; END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT payment.status_code AS payment_status,
            proposal.status_code AS proposal_status,
            proposal.brief_id, proposal.brief_version_id,
            decision.id AS decision_id, decision.decision_code,
            option.id AS option_id, option.plan_version_id,
            plan.status_code AS plan_status,
            min(line.flight_start) AS start_date,
            max(line.flight_end) AS end_date,
            brief.owner_user_id, brief_version.measurement_json,
            count(line.id)::integer AS required_count
        INTO expected
        FROM commercial.payment_intents payment
        JOIN commercial.proposal_versions proposal
          ON proposal.tenant_id = payment.tenant_id
         AND proposal.id = payment.proposal_version_id
        JOIN commercial.proposal_decisions decision
          ON decision.tenant_id = proposal.tenant_id
         AND decision.proposal_version_id = proposal.id
        JOIN commercial.proposal_options option
          ON option.tenant_id = decision.tenant_id
         AND option.id = decision.option_id
         AND option.id = payment.proposal_option_id
        JOIN commercial.media_plan_versions plan
          ON plan.tenant_id = option.tenant_id
         AND plan.id = option.plan_version_id
        JOIN commercial.media_plan_lines line
          ON line.tenant_id = option.tenant_id
         AND line.plan_version_id = option.plan_version_id
        JOIN commercial.campaign_briefs brief
          ON brief.tenant_id = proposal.tenant_id AND brief.id = proposal.brief_id
        JOIN commercial.brief_versions brief_version
          ON brief_version.tenant_id = proposal.tenant_id
         AND brief_version.id = proposal.brief_version_id
        WHERE payment.tenant_id = NEW.tenant_id
          AND payment.id = NEW.payment_intent_id
        GROUP BY payment.status_code, proposal.status_code,
            proposal.brief_id, proposal.brief_version_id, decision.id,
            decision.decision_code, option.id, option.plan_version_id,
            plan.status_code, brief.owner_user_id,
            brief_version.measurement_json;
        IF NOT FOUND OR expected.payment_status <> 'CONFIRMED'
           OR expected.proposal_status <> 'SELECTED'
           OR expected.decision_code <> 'SELECTED'
           OR expected.plan_status <> 'APPROVED'
           OR expected.required_count <= 0
           OR (NEW.brief_id, NEW.brief_version_id,
               NEW.proposal_decision_id, NEW.proposal_option_id,
               NEW.plan_version_id, NEW.start_date, NEW.end_date,
               NEW.owner_user_id, NEW.measurement_plan_json)
              IS DISTINCT FROM
              (expected.brief_id, expected.brief_version_id,
               expected.decision_id, expected.option_id,
               expected.plan_version_id, expected.start_date,
               expected.end_date, expected.owner_user_id,
               expected.measurement_json)
           OR NEW.status_code <> 'PLANNED'
           OR NEW.created_by <> commercial.current_user_id() THEN
            RAISE EXCEPTION 'campaign does not reconcile to confirmed funding';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.tenant_id, NEW.brief_id, NEW.brief_version_id,
        NEW.proposal_version_id, NEW.proposal_option_id,
        NEW.proposal_decision_id, NEW.plan_version_id,
        NEW.payment_intent_id, NEW.title, NEW.start_date, NEW.end_date,
        NEW.owner_user_id, NEW.measurement_plan_json,
        NEW.created_by, NEW.created_at_utc) IS DISTINCT FROM
       (OLD.id, OLD.tenant_id, OLD.brief_id, OLD.brief_version_id,
        OLD.proposal_version_id, OLD.proposal_option_id,
        OLD.proposal_decision_id, OLD.plan_version_id,
        OLD.payment_intent_id, OLD.title, OLD.start_date, OLD.end_date,
        OLD.owner_user_id, OLD.measurement_plan_json,
        OLD.created_by, OLD.created_at_utc) THEN
        RAISE EXCEPTION 'campaign source snapshot is immutable';
    END IF;
    IF OLD.status_code = 'PLANNED' AND NEW.status_code = 'BOOKED' THEN
        IF NEW.bookings_confirmed_by <> commercial.current_user_id()
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at_utc < OLD.updated_at_utc
           OR EXISTS (
               SELECT 1 FROM commercial.media_plan_lines line
               WHERE line.tenant_id = OLD.tenant_id
                 AND line.plan_version_id = OLD.plan_version_id
                 AND NOT EXISTS (
                     SELECT 1 FROM commercial.bookings booking
                     WHERE booking.buyer_tenant_id = OLD.tenant_id
                       AND booking.proposal_decision_id = OLD.proposal_decision_id
                       AND booking.media_plan_line_id = line.id
                       AND booking.status_code = 'CONFIRMED')) THEN
            RAISE EXCEPTION 'campaign bookings are not ready';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'BOOKED' AND NEW.status_code = 'CREATIVE_PENDING' THEN
        SELECT count(*)::integer INTO requirement_count
        FROM commercial.creative_requirements requirement
        WHERE requirement.buyer_tenant_id = OLD.tenant_id
          AND requirement.campaign_id = OLD.id;
        SELECT count(*)::integer INTO booking_count
        FROM commercial.bookings booking
        WHERE booking.buyer_tenant_id = OLD.tenant_id
          AND booking.proposal_decision_id = OLD.proposal_decision_id
          AND booking.plan_version_id = OLD.plan_version_id
          AND booking.status_code = 'CONFIRMED';
        IF (NEW.bookings_confirmed_by, NEW.bookings_confirmed_at_utc,
            NEW.booking_confirmation_reason) IS DISTINCT FROM
           (OLD.bookings_confirmed_by, OLD.bookings_confirmed_at_utc,
            OLD.booking_confirmation_reason)
           OR NEW.creative_requested_by <> commercial.current_user_id()
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at_utc < OLD.updated_at_utc
           OR requirement_count <= 0 OR requirement_count <> booking_count
           OR EXISTS (
               SELECT 1 FROM commercial.bookings booking
               WHERE booking.buyer_tenant_id = OLD.tenant_id
                 AND booking.proposal_decision_id = OLD.proposal_decision_id
                 AND booking.plan_version_id = OLD.plan_version_id
                 AND booking.status_code = 'CONFIRMED'
                 AND NOT EXISTS (
                     SELECT 1 FROM commercial.creative_requirements requirement
                     WHERE requirement.buyer_tenant_id = OLD.tenant_id
                       AND requirement.campaign_id = OLD.id
                       AND requirement.booking_id = booking.id)) THEN
            RAISE EXCEPTION 'creative requirements do not cover confirmed bookings';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'CREATIVE_PENDING' AND NEW.status_code = 'READY' THEN
        IF (NEW.bookings_confirmed_by, NEW.bookings_confirmed_at_utc,
            NEW.booking_confirmation_reason, NEW.creative_requested_by,
            NEW.creative_requested_at_utc, NEW.creative_request_reason)
           IS DISTINCT FROM
           (OLD.bookings_confirmed_by, OLD.bookings_confirmed_at_utc,
            OLD.booking_confirmation_reason, OLD.creative_requested_by,
            OLD.creative_requested_at_utc, OLD.creative_request_reason)
           OR NEW.creative_approved_by <> commercial.current_user_id()
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at_utc < OLD.updated_at_utc
           OR NOT EXISTS (
               SELECT 1 FROM commercial.creative_requirements requirement
               WHERE requirement.buyer_tenant_id = OLD.tenant_id
                 AND requirement.campaign_id = OLD.id)
           OR EXISTS (
               SELECT 1 FROM commercial.creative_requirements requirement
               WHERE requirement.buyer_tenant_id = OLD.tenant_id
                 AND requirement.campaign_id = OLD.id
                 AND NOT EXISTS (
                     SELECT 1 FROM commercial.creative_assets asset
                     JOIN commercial.creative_asset_reviews brand
                       ON brand.buyer_tenant_id = asset.buyer_tenant_id
                      AND brand.asset_version_id = asset.current_version_id
                      AND brand.review_type_code = 'BRAND_LEGAL_RIGHTS'
                      AND brand.decision_code = 'APPROVED'
                      AND brand.rights_status_code = 'APPROVED'
                     JOIN commercial.creative_asset_reviews supplier
                       ON supplier.buyer_tenant_id = asset.buyer_tenant_id
                      AND supplier.asset_version_id = asset.current_version_id
                      AND supplier.review_type_code = 'SUPPLIER_TECHNICAL'
                      AND supplier.decision_code = 'APPROVED'
                     WHERE asset.buyer_tenant_id = OLD.tenant_id
                       AND asset.requirement_id = requirement.id
                       AND asset.current_version_id IS NOT NULL)) THEN
            RAISE EXCEPTION 'campaign creative is not ready';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'READY' AND NEW.status_code = 'LIVE' THEN
        IF (NEW.bookings_confirmed_by, NEW.bookings_confirmed_at_utc,
            NEW.booking_confirmation_reason, NEW.creative_requested_by,
            NEW.creative_requested_at_utc, NEW.creative_request_reason,
            NEW.creative_approved_by, NEW.creative_approved_at_utc,
            NEW.creative_approval_reason) IS DISTINCT FROM
           (OLD.bookings_confirmed_by, OLD.bookings_confirmed_at_utc,
            OLD.booking_confirmation_reason, OLD.creative_requested_by,
            OLD.creative_requested_at_utc, OLD.creative_request_reason,
            OLD.creative_approved_by, OLD.creative_approved_at_utc,
            OLD.creative_approval_reason)
           OR NEW.started_by <> commercial.current_user_id()
           OR (NEW.started_at_utc AT TIME ZONE 'UTC')::date
                NOT BETWEEN OLD.start_date AND OLD.end_date
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at_utc <> NEW.started_at_utc
           OR NOT EXISTS (
               SELECT 1 FROM commercial.payment_intents payment
               WHERE payment.tenant_id = OLD.tenant_id
                 AND payment.id = OLD.payment_intent_id
                 AND payment.status_code = 'CONFIRMED')
           OR EXISTS (
               SELECT 1 FROM commercial.media_plan_lines line
               WHERE line.tenant_id = OLD.tenant_id
                 AND line.plan_version_id = OLD.plan_version_id
                 AND NOT EXISTS (
                     SELECT 1 FROM commercial.bookings booking
                     WHERE booking.buyer_tenant_id = OLD.tenant_id
                       AND booking.proposal_decision_id = OLD.proposal_decision_id
                       AND booking.media_plan_line_id = line.id
                       AND booking.status_code = 'CONFIRMED'))
           OR EXISTS (
               SELECT 1 FROM commercial.creative_requirements requirement
               WHERE requirement.buyer_tenant_id = OLD.tenant_id
                 AND requirement.campaign_id = OLD.id
                 AND NOT EXISTS (
                     SELECT 1 FROM commercial.creative_assets asset
                     JOIN commercial.creative_asset_reviews brand
                       ON brand.buyer_tenant_id = asset.buyer_tenant_id
                      AND brand.asset_version_id = asset.current_version_id
                      AND brand.review_type_code = 'BRAND_LEGAL_RIGHTS'
                      AND brand.decision_code = 'APPROVED'
                      AND brand.rights_status_code = 'APPROVED'
                     JOIN commercial.creative_asset_reviews supplier
                       ON supplier.buyer_tenant_id = asset.buyer_tenant_id
                      AND supplier.asset_version_id = asset.current_version_id
                      AND supplier.review_type_code = 'SUPPLIER_TECHNICAL'
                      AND supplier.decision_code = 'APPROVED'
                     WHERE asset.buyer_tenant_id = OLD.tenant_id
                       AND asset.requirement_id = requirement.id
                       AND asset.current_version_id IS NOT NULL)) THEN
            RAISE EXCEPTION 'campaign delivery dependencies are not ready';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'LIVE' AND NEW.status_code = 'COMPLETED' THEN
        IF (NEW.bookings_confirmed_by, NEW.bookings_confirmed_at_utc,
            NEW.booking_confirmation_reason, NEW.creative_requested_by,
            NEW.creative_requested_at_utc, NEW.creative_request_reason,
            NEW.creative_approved_by, NEW.creative_approved_at_utc,
            NEW.creative_approval_reason, NEW.started_by,
            NEW.started_at_utc, NEW.start_reason) IS DISTINCT FROM
           (OLD.bookings_confirmed_by, OLD.bookings_confirmed_at_utc,
            OLD.booking_confirmation_reason, OLD.creative_requested_by,
            OLD.creative_requested_at_utc, OLD.creative_request_reason,
            OLD.creative_approved_by, OLD.creative_approved_at_utc,
            OLD.creative_approval_reason, OLD.started_by,
            OLD.started_at_utc, OLD.start_reason)
           OR NEW.completed_by <> commercial.current_user_id()
           OR NEW.proof_requested_by <> commercial.current_user_id()
           OR NEW.proof_requested_at_utc <> NEW.completed_at_utc
           OR (NEW.completed_at_utc AT TIME ZONE 'UTC')::date <= OLD.end_date
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at_utc <> NEW.completed_at_utc THEN
            RAISE EXCEPTION 'campaign delivery is not complete';
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'campaign lifecycle transition is invalid';
END;
$$;
CREATE FUNCTION commercial.enforce_creative_asset() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE campaign_status varchar(100);
BEGIN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'creative assets cannot be deleted'; END IF;
    SELECT campaign.status_code INTO campaign_status
    FROM commercial.campaigns campaign
    WHERE campaign.tenant_id = NEW.buyer_tenant_id
      AND campaign.id = NEW.campaign_id;
    IF TG_OP = 'INSERT' THEN
        IF NEW.buyer_tenant_id <> commercial.current_tenant_id()
           OR NEW.created_by <> commercial.current_user_id()
           OR NEW.current_version_id IS NOT NULL OR NEW.version <> 0
           OR campaign_status <> 'CREATIVE_PENDING' THEN
            RAISE EXCEPTION 'creative asset cannot be created';
        END IF;
        RETURN NEW;
    END IF;
    IF campaign_status <> 'CREATIVE_PENDING'
       OR (NEW.id, NEW.buyer_tenant_id, NEW.supplier_tenant_id,
           NEW.campaign_id, NEW.requirement_id, NEW.created_by, NEW.created_at_utc)
          IS DISTINCT FROM
          (OLD.id, OLD.buyer_tenant_id, OLD.supplier_tenant_id,
           OLD.campaign_id, OLD.requirement_id, OLD.created_by, OLD.created_at_utc)
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at_utc < OLD.updated_at_utc THEN
        RAISE EXCEPTION 'creative asset version pointer is invalid';
    END IF;
    IF NEW.current_version_id IS DISTINCT FROM OLD.current_version_id THEN
        IF NEW.buyer_tenant_id <> commercial.current_tenant_id()
           OR NOT EXISTS (
           SELECT 1 FROM commercial.creative_asset_versions version
           LEFT JOIN commercial.creative_asset_versions prior
             ON prior.buyer_tenant_id = OLD.buyer_tenant_id
            AND prior.id = OLD.current_version_id
           WHERE version.buyer_tenant_id = NEW.buyer_tenant_id
             AND version.supplier_tenant_id = NEW.supplier_tenant_id
             AND version.id = NEW.current_version_id
             AND version.asset_id = NEW.id
             AND version.requirement_id = NEW.requirement_id
             AND version.version_number = COALESCE(prior.version_number, 0) + 1) THEN
            RAISE EXCEPTION 'creative asset version pointer is invalid';
        END IF;
    ELSIF NEW.version <> (
        SELECT count(*) FROM commercial.creative_asset_versions version
        WHERE version.buyer_tenant_id = NEW.buyer_tenant_id
          AND version.asset_id = NEW.id) + (
        SELECT count(*) FROM commercial.creative_asset_reviews review
        WHERE review.buyer_tenant_id = NEW.buyer_tenant_id
          AND review.asset_id = NEW.id)
       OR NOT EXISTS (
        SELECT 1 FROM commercial.creative_asset_reviews review
        WHERE review.buyer_tenant_id = NEW.buyer_tenant_id
          AND review.asset_id = NEW.id
          AND review.asset_version_id = NEW.current_version_id
          AND review.reviewed_by = commercial.current_user_id()
          AND review.reviewer_tenant_id = commercial.current_tenant_id()
          AND review.reviewed_at_utc = NEW.updated_at_utc) THEN
        RAISE EXCEPTION 'creative review does not match the asset update';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_creative_asset_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'creative reviews are immutable';
    END IF;
    SELECT asset.current_version_id, campaign.status_code AS campaign_status
    INTO expected
    FROM commercial.creative_assets asset
    JOIN commercial.campaigns campaign
      ON campaign.tenant_id = asset.buyer_tenant_id
     AND campaign.id = asset.campaign_id
    WHERE asset.buyer_tenant_id = NEW.buyer_tenant_id
      AND asset.supplier_tenant_id = NEW.supplier_tenant_id
      AND asset.id = NEW.asset_id;
    IF NOT FOUND OR NEW.reviewed_by <> commercial.current_user_id()
       OR NEW.reviewer_tenant_id <> commercial.current_tenant_id()
       OR expected.campaign_status <> 'CREATIVE_PENDING'
       OR NEW.asset_version_id <> expected.current_version_id
       OR (NEW.review_type_code = 'BRAND_LEGAL_RIGHTS'
           AND NEW.buyer_tenant_id <> commercial.current_tenant_id())
       OR (NEW.review_type_code = 'SUPPLIER_TECHNICAL'
           AND NEW.supplier_tenant_id <> commercial.current_tenant_id()) THEN
        RAISE EXCEPTION 'creative review is not authorised for the current version';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_creative_asset_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
DECLARE expected_commercial jsonb;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'creative asset versions are immutable';
    END IF;
    SELECT current.version_number AS current_version_number, asset.requirement_id,
        requirement.required_media_type, requirement.maximum_bytes,
        campaign.status_code AS campaign_status, campaign.version AS campaign_version,
        booking.version AS booking_version, booking.currency_code,
        booking.supplier_cost_minor, booking.client_price_minor,
        booking.fees_minor, booking.vat_minor
    INTO expected
    FROM commercial.creative_assets asset
    LEFT JOIN commercial.creative_asset_versions current
      ON current.buyer_tenant_id = asset.buyer_tenant_id
     AND current.id = asset.current_version_id
    JOIN commercial.creative_requirements requirement
      ON requirement.buyer_tenant_id = asset.buyer_tenant_id
     AND requirement.id = asset.requirement_id
    JOIN commercial.campaigns campaign
      ON campaign.tenant_id = asset.buyer_tenant_id
     AND campaign.id = asset.campaign_id
    JOIN commercial.bookings booking
      ON booking.buyer_tenant_id = requirement.buyer_tenant_id
     AND booking.supplier_tenant_id = requirement.supplier_tenant_id
     AND booking.id = requirement.booking_id
    WHERE asset.buyer_tenant_id = NEW.buyer_tenant_id
      AND asset.supplier_tenant_id = NEW.supplier_tenant_id
      AND asset.id = NEW.asset_id;
    expected_commercial := jsonb_build_object(
        'currency', expected.currency_code,
        'supplierCostMinor', expected.supplier_cost_minor,
        'clientPriceMinor', expected.client_price_minor,
        'feesMinor', expected.fees_minor,
        'vatMinor', expected.vat_minor);
    IF NOT FOUND OR NEW.buyer_tenant_id <> commercial.current_tenant_id()
       OR NEW.created_by <> commercial.current_user_id()
       OR expected.campaign_status <> 'CREATIVE_PENDING'
       OR NEW.requirement_id <> expected.requirement_id
       OR NEW.version_number <> COALESCE(expected.current_version_number, 0) + 1
       OR NEW.media_type <> expected.required_media_type
       OR NEW.size_bytes > expected.maximum_bytes
       OR NEW.campaign_version <> expected.campaign_version
       OR NEW.booking_version <> expected.booking_version
       OR NEW.commercial_snapshot_json IS DISTINCT FROM expected_commercial
       OR btrim(NEW.approved_copy) = '' THEN
        RAISE EXCEPTION 'creative asset version does not match its requirement';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_creative_requirement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'creative requirements are immutable';
    END IF;
    SELECT campaign.status_code AS campaign_status,
        booking.supplier_tenant_id, booking.media_plan_line_id,
        booking.channel_code, booking.flight_start, booking.flight_end,
        booking.status_code AS booking_status
    INTO expected
    FROM commercial.campaigns campaign
    JOIN commercial.bookings booking
      ON booking.buyer_tenant_id = campaign.tenant_id
     AND booking.proposal_decision_id = campaign.proposal_decision_id
     AND booking.plan_version_id = campaign.plan_version_id
    WHERE campaign.tenant_id = NEW.buyer_tenant_id
      AND campaign.id = NEW.campaign_id
      AND booking.id = NEW.booking_id;
    IF NOT FOUND OR NEW.buyer_tenant_id <> commercial.current_tenant_id()
       OR NEW.created_by <> commercial.current_user_id()
       OR expected.campaign_status <> 'BOOKED'
       OR expected.booking_status <> 'CONFIRMED'
       OR (NEW.supplier_tenant_id, NEW.media_plan_line_id,
           NEW.channel_code, NEW.flight_start, NEW.flight_end)
          IS DISTINCT FROM
          (expected.supplier_tenant_id, expected.media_plan_line_id,
           expected.channel_code, expected.flight_start, expected.flight_end) THEN
        RAISE EXCEPTION 'creative requirement does not match a confirmed booking';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_current_inventory_extraction_artifact() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
BEGIN
    IF NEW.attempt_id IS NULL THEN
        RETURN NEW;
    END IF;
    PERFORM 1
    FROM commercial.inventory_extraction_attempts attempt
    WHERE attempt.tenant_id = NEW.tenant_id
      AND attempt.id = NEW.attempt_id
      AND attempt.import_id = NEW.import_id
      AND attempt.source_hash = NEW.source_hash
      AND attempt.source_file_version = NEW.source_file_version
      AND attempt.status_code = 'RUNNING'
      AND attempt.extracted_artifact_id IS NULL
      AND attempt.worker_lease_token IS NOT NULL
      AND attempt.worker_lease_expires_at_utc > pg_catalog.statement_timestamp()
      AND NOT EXISTS (
          SELECT 1
          FROM commercial.inventory_extraction_attempts newer
          WHERE newer.tenant_id = attempt.tenant_id
            AND newer.import_id = attempt.import_id
            AND newer.attempt_number > attempt.attempt_number)
    FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION
            'extraction artifact must belong to the current leased running attempt'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_delivery_proof() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'delivery proofs cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT campaign.status_code AS campaign_status,
            campaign.proof_requested_at_utc,
            booking.status_code AS booking_status,
            booking.flight_start, booking.flight_end,
            booking.supplier_tenant_id
        INTO expected
        FROM commercial.campaigns campaign
        JOIN commercial.bookings booking
          ON booking.buyer_tenant_id = campaign.tenant_id
         AND booking.proposal_decision_id = campaign.proposal_decision_id
         AND booking.plan_version_id = campaign.plan_version_id
        WHERE campaign.tenant_id = NEW.buyer_tenant_id
          AND campaign.id = NEW.campaign_id
          AND booking.id = NEW.booking_id;
        IF NOT FOUND OR expected.campaign_status <> 'COMPLETED'
           OR expected.proof_requested_at_utc IS NULL
           OR expected.booking_status <> 'CONFIRMED'
           OR NEW.supplier_tenant_id <> expected.supplier_tenant_id
           OR NEW.submitter_tenant_id <> commercial.current_tenant_id()
           OR NEW.submitted_by <> commercial.current_user_id()
           OR NEW.status_code <> 'SUBMITTED' OR NEW.version <> 1
           OR (NEW.captured_at_utc AT TIME ZONE 'UTC')::date
                NOT BETWEEN expected.flight_start AND expected.flight_end
           OR NEW.submitted_at_utc < NEW.captured_at_utc
           OR NEW.updated_at_utc <> NEW.submitted_at_utc
           OR NEW.protected_object_key <>
                'protected/' || replace(NEW.buyer_tenant_id::text, '-', '') ||
                '/campaigns/' || replace(NEW.campaign_id::text, '-', '') ||
                '/proof/' || replace(NEW.id::text, '-', '') || '/' ||
                NEW.content_sha256 THEN
            RAISE EXCEPTION 'delivery proof does not match an eligible booking';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.buyer_tenant_id <> commercial.current_tenant_id()
       OR OLD.status_code <> 'SUBMITTED'
       OR NEW.status_code NOT IN ('APPROVED', 'REJECTED')
       OR NEW.reviewed_by <> commercial.current_user_id()
       OR NEW.reviewed_by = OLD.submitted_by
       OR NEW.reviewed_at_utc IS NULL
       OR NEW.reviewed_at_utc < OLD.submitted_at_utc
       OR NEW.updated_at_utc <> NEW.reviewed_at_utc
       OR NEW.version <> OLD.version + 1
       OR (NEW.id, NEW.buyer_tenant_id, NEW.supplier_tenant_id,
           NEW.campaign_id, NEW.booking_id,
           NEW.proof_type_collection_code, NEW.proof_type_code,
           NEW.file_name, NEW.media_type, NEW.size_bytes,
           NEW.content_sha256, NEW.signature_validated,
           NEW.malware_scan_status_collection_code,
           NEW.malware_scan_status_code, NEW.protected_object_key,
           NEW.captured_at_utc, NEW.location_description,
           NEW.latitude, NEW.longitude, NEW.source_reference,
           NEW.submission_reason, NEW.submitted_by,
           NEW.submitter_tenant_id, NEW.submitted_at_utc)
          IS DISTINCT FROM
          (OLD.id, OLD.buyer_tenant_id, OLD.supplier_tenant_id,
           OLD.campaign_id, OLD.booking_id,
           OLD.proof_type_collection_code, OLD.proof_type_code,
           OLD.file_name, OLD.media_type, OLD.size_bytes,
           OLD.content_sha256, OLD.signature_validated,
           OLD.malware_scan_status_collection_code,
           OLD.malware_scan_status_code, OLD.protected_object_key,
           OLD.captured_at_utc, OLD.location_description,
           OLD.latitude, OLD.longitude, OLD.source_reference,
           OLD.submission_reason, OLD.submitted_by,
           OLD.submitter_tenant_id, OLD.submitted_at_utc) THEN
        RAISE EXCEPTION 'delivery proof review is invalid';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_email_delivery_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.delivery_provider_collection_code IS NOT NULL
       AND (NEW.delivery_provider_collection_code IS DISTINCT FROM
                OLD.delivery_provider_collection_code
            OR NEW.delivery_provider_code IS DISTINCT FROM
                OLD.delivery_provider_code) THEN
        RAISE EXCEPTION 'email delivery provider is immutable';
    END IF;
    IF OLD.delivery_idempotency_key IS NOT NULL
       AND NEW.delivery_idempotency_key IS DISTINCT FROM
            OLD.delivery_idempotency_key THEN
        RAISE EXCEPTION 'email delivery idempotency key is immutable';
    END IF;
    IF OLD.delivery_requested_at_utc IS NOT NULL
       AND NEW.delivery_requested_at_utc IS DISTINCT FROM
            OLD.delivery_requested_at_utc THEN
        RAISE EXCEPTION 'email delivery request evidence is immutable';
    END IF;
    IF OLD.delivery_accepted_at_utc IS NOT NULL
       AND (NEW.delivery_accepted_at_utc IS DISTINCT FROM
                OLD.delivery_accepted_at_utc
            OR NEW.delivery_provider_id IS DISTINCT FROM
                OLD.delivery_provider_id) THEN
        RAISE EXCEPTION 'email delivery acceptance evidence is immutable';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_inventory_duplicate_review() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE'
       OR OLD.id IS DISTINCT FROM NEW.id
       OR OLD.tenant_id IS DISTINCT FROM NEW.tenant_id
       OR OLD.left_product_id IS DISTINCT FROM NEW.left_product_id
       OR OLD.right_product_id IS DISTINCT FROM NEW.right_product_id
       OR OLD.left_product_version_id IS DISTINCT FROM NEW.left_product_version_id
       OR OLD.right_product_version_id IS DISTINCT FROM NEW.right_product_version_id
       OR OLD.method_collection_code IS DISTINCT FROM NEW.method_collection_code
       OR OLD.method_code IS DISTINCT FROM NEW.method_code
       OR OLD.similarity IS DISTINCT FROM NEW.similarity
       OR OLD.evidence_json IS DISTINCT FROM NEW.evidence_json
       OR OLD.status_collection_code IS DISTINCT FROM NEW.status_collection_code
       OR OLD.detected_at_utc IS DISTINCT FROM NEW.detected_at_utc
       OR OLD.status_code <> 'OPEN'
       OR NEW.status_code = 'OPEN'
       OR NEW.version <> OLD.version + 1
       OR NEW.reviewed_by IS DISTINCT FROM commercial.current_user_id()
    THEN
        RAISE EXCEPTION 'inventory duplicate candidate review transition is invalid';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_inventory_extraction_attempt_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
BEGIN
    IF (NEW.tenant_id, NEW.import_id, NEW.source_file_version, NEW.source_hash,
        NEW.stable_submission_key, NEW.provider_name, NEW.provider_version,
        NEW.attempt_number, NEW.correlation_id, NEW.command_id, NEW.requested_by)
       IS DISTINCT FROM
       (OLD.tenant_id, OLD.import_id, OLD.source_file_version, OLD.source_hash,
        OLD.stable_submission_key, OLD.provider_name, OLD.provider_version,
        OLD.attempt_number, OLD.correlation_id, OLD.command_id, OLD.requested_by) THEN
        RAISE EXCEPTION 'immutable extraction attempt identity cannot change'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.external_task_id IS NOT NULL AND
       NEW.external_task_id IS DISTINCT FROM OLD.external_task_id THEN
        RAISE EXCEPTION 'external extraction task identity cannot change'
            USING ERRCODE = '23514';
    END IF;
    IF OLD.extracted_artifact_id IS NOT NULL AND
       NEW.extracted_artifact_id IS DISTINCT FROM OLD.extracted_artifact_id THEN
        RAISE EXCEPTION 'accepted extraction artifact cannot change'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.status_code <> OLD.status_code AND NOT (
        (OLD.status_code = 'PENDING' AND NEW.status_code IN (
            'SUBMITTING', 'FAILED_TERMINAL', 'CANCELLED')) OR
        (OLD.status_code = 'SUBMITTING' AND NEW.status_code IN (
            'RUNNING', 'FAILED_TERMINAL', 'RECONCILIATION_REQUIRED', 'CANCELLED')) OR
        (OLD.status_code = 'RUNNING' AND NEW.status_code IN (
            'COMPLETED', 'FAILED_RETRYABLE', 'FAILED_TERMINAL', 'TIMED_OUT',
            'RECONCILIATION_REQUIRED', 'CANCELLED')) OR
        (OLD.status_code = 'FAILED_RETRYABLE' AND NEW.status_code IN (
            'RUNNING', 'FAILED_TERMINAL', 'TIMED_OUT',
            'RECONCILIATION_REQUIRED', 'CANCELLED')) OR
        (OLD.status_code = 'RECONCILIATION_REQUIRED' AND
            NEW.status_code IN ('RUNNING', 'CANCELLED'))) THEN
        RAISE EXCEPTION 'invalid extraction attempt transition: % -> %',
            OLD.status_code, NEW.status_code USING ERRCODE = '23514';
    END IF;
    IF NEW.status_code = 'COMPLETED' AND EXISTS (
        SELECT 1 FROM commercial.inventory_extraction_attempts newer
        WHERE newer.tenant_id = NEW.tenant_id
          AND newer.import_id = NEW.import_id
          AND newer.attempt_number > NEW.attempt_number) THEN
        RAISE EXCEPTION 'an obsolete extraction attempt cannot be accepted'
            USING ERRCODE = '23514';
    END IF;
    NEW.version := OLD.version + 1;
    NEW.updated_at_utc := pg_catalog.statement_timestamp();
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_inventory_identity_link() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM commercial.inventory_product_identity_links link
        WHERE link.tenant_id = NEW.tenant_id
          AND (link.duplicate_product_id IN (
                NEW.duplicate_product_id, NEW.canonical_product_id)
            OR link.canonical_product_id = NEW.duplicate_product_id))
    THEN
        RAISE EXCEPTION 'inventory identity links cannot form chains or cycles';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_invoice_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'invoices are immutable'; END IF;
    SELECT po.status_code, po.proposal_version_id, po.proposal_option_id,
        po.amount_minor, po.currency_code, plan.subtotal_minor,
        plan.fees_minor, plan.vat_minor, plan.total_minor
    INTO expected
    FROM commercial.purchase_orders po
    JOIN commercial.media_plan_versions plan
      ON plan.tenant_id = po.tenant_id AND plan.id = po.plan_version_id
    WHERE po.tenant_id = NEW.tenant_id AND po.id = NEW.purchase_order_id;
    IF NOT FOUND OR expected.status_code <> 'APPROVED'
       OR NEW.status_code <> 'ISSUED'
       OR NEW.issued_by <> commercial.current_user_id()
       OR (NEW.proposal_version_id, NEW.proposal_option_id, NEW.total_minor,
           NEW.currency_code, NEW.subtotal_minor, NEW.fees_minor, NEW.vat_minor)
          IS DISTINCT FROM
          (expected.proposal_version_id, expected.proposal_option_id,
           expected.total_minor, expected.currency_code, expected.subtotal_minor,
           expected.fees_minor, expected.vat_minor)
       OR NEW.total_minor <> expected.amount_minor THEN
        RAISE EXCEPTION 'invoice does not reconcile to approved purchase order';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_measurement_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE expected record;
DECLARE expected_evidence integer;
DECLARE expected_metrics integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'measurement reports cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT campaign.version AS campaign_version,
            campaign.measurement_plan_json, brief.opportunity_id
        INTO expected
        FROM commercial.campaigns campaign
        JOIN commercial.campaign_briefs brief
          ON brief.tenant_id = campaign.tenant_id AND brief.id = campaign.brief_id
        WHERE campaign.tenant_id = NEW.tenant_id
          AND campaign.id = NEW.campaign_id
          AND campaign.status_code = 'COMPLETED';
        SELECT count(DISTINCT evidence.id)::integer, count(metric.id)::integer
        INTO expected_evidence, expected_metrics
        FROM commercial.performance_evidence_sets evidence
        LEFT JOIN commercial.performance_metrics metric
          ON metric.tenant_id = evidence.tenant_id
         AND metric.evidence_set_id = evidence.id
        WHERE evidence.tenant_id = NEW.tenant_id
          AND evidence.campaign_id = NEW.campaign_id
          AND evidence.status_code = 'APPROVED';
        IF NOT FOUND OR NEW.tenant_id <> commercial.current_tenant_id()
           OR NEW.generated_by <> commercial.current_user_id()
           OR NEW.approver_user_id = NEW.generated_by
           OR NEW.status_code <> 'REVIEW_REQUIRED' OR NEW.version <> 1
           OR NEW.generated_at_utc <> NEW.updated_at_utc
           OR NEW.campaign_version <> expected.campaign_version
           OR NEW.measurement_plan_json <> expected.measurement_plan_json
           OR expected_evidence = 0 OR expected_metrics = 0
           OR jsonb_array_length(NEW.evidence_versions_json) <> expected_evidence
           OR cardinality(NEW.metric_ids) <> expected_metrics
           OR EXISTS (
               SELECT 1 FROM commercial.performance_evidence_sets evidence
               WHERE evidence.tenant_id = NEW.tenant_id
                 AND evidence.campaign_id = NEW.campaign_id
                 AND evidence.status_code = 'APPROVED'
                 AND NOT EXISTS (
                    SELECT 1 FROM jsonb_array_elements(
                        NEW.evidence_versions_json) item
                    WHERE (item->>'id')::uuid = evidence.id
                      AND (item->>'version')::bigint = evidence.version))
           OR EXISTS (
               SELECT 1 FROM unnest(NEW.metric_ids) supplied(id)
               WHERE NOT EXISTS (
                    SELECT 1 FROM commercial.performance_metrics metric
                    JOIN commercial.performance_evidence_sets evidence
                      ON evidence.tenant_id = metric.tenant_id
                     AND evidence.id = metric.evidence_set_id
                    WHERE metric.tenant_id = NEW.tenant_id
                      AND metric.id = supplied.id
                      AND evidence.campaign_id = NEW.campaign_id
                      AND evidence.status_code = 'APPROVED'))
           OR EXISTS (
               SELECT 1 FROM commercial.performance_metrics metric
               JOIN commercial.performance_evidence_sets evidence
                 ON evidence.tenant_id = metric.tenant_id
                AND evidence.id = metric.evidence_set_id
               WHERE metric.tenant_id = NEW.tenant_id
                 AND evidence.campaign_id = NEW.campaign_id
                 AND evidence.status_code = 'APPROVED'
                 AND NOT metric.id = ANY(NEW.metric_ids))
           OR jsonb_typeof(NEW.interpretation_json) <> 'object'
           OR NEW.interpretation_json->>'causalityStatus' <> 'NOT_ESTABLISHED'
           OR NEW.interpretation_json->'limitations' <> NEW.limitations_json
           OR jsonb_array_length(NEW.limitations_json) <> (
               SELECT count(DISTINCT limitation #>> '{}')::integer
               FROM commercial.performance_evidence_sets evidence
               CROSS JOIN jsonb_array_elements(
                    evidence.limitations_json) limitation
               WHERE evidence.tenant_id = NEW.tenant_id
                 AND evidence.campaign_id = NEW.campaign_id
                 AND evidence.status_code = 'APPROVED')
           OR EXISTS (
               SELECT 1 FROM commercial.performance_evidence_sets evidence
               CROSS JOIN jsonb_array_elements(
                    evidence.limitations_json) limitation
               WHERE evidence.tenant_id = NEW.tenant_id
                 AND evidence.campaign_id = NEW.campaign_id
                 AND evidence.status_code = 'APPROVED'
                 AND NOT NEW.limitations_json @> jsonb_build_array(limitation))
           OR NOT EXISTS (SELECT 1 FROM commercial.agent_runs run
               JOIN commercial.agent_run_steps step
                 ON step.tenant_id = run.tenant_id AND step.run_id = run.id
               JOIN commercial.ai_usage_ledger usage
                 ON usage.tenant_id = step.tenant_id AND usage.step_id = step.id
               WHERE run.tenant_id = NEW.tenant_id AND run.id = NEW.agent_run_id
                 AND run.campaign_id = NEW.campaign_id
                 AND run.opportunity_id IS NOT DISTINCT FROM expected.opportunity_id
                 AND run.run_kind_code = 'MEASUREMENT'
                 AND run.status_code = 'COMPLETED'
                 AND run.input_version = NEW.campaign_version
                 AND run.requested_by = NEW.generated_by
                 AND run.approver_user_id = NEW.approver_user_id
                 AND step.step_code = 'MEASUREMENT'
                 AND step.agent_code = 'measurement'
                 AND step.status_code = 'COMPLETED'
                 AND step.input_hash = NEW.input_hash
                 AND step.output_json->'interpretation' = NEW.interpretation_json
                 AND usage.provider_code = NEW.provider_code
                 AND usage.model_code = NEW.model_code
                 AND usage.units = 0
                 AND usage.tool_calls = NEW.tool_calls
                 AND usage.incremental_cost_minor = NEW.incremental_cost_minor
                 AND usage.cache_status_code = 'FIXTURE')
           OR (SELECT count(*) FROM commercial.agent_run_steps step
               WHERE step.tenant_id = NEW.tenant_id
                 AND step.run_id = NEW.agent_run_id) <> 1
           OR (SELECT count(*) FROM commercial.ai_usage_ledger usage
               WHERE usage.tenant_id = NEW.tenant_id
                 AND usage.run_id = NEW.agent_run_id) <> 1
           OR NOT EXISTS (SELECT 1 FROM commercial.memberships membership
               WHERE membership.tenant_id = NEW.tenant_id
                 AND membership.user_id = NEW.generated_by
                 AND membership.status_code = 'ACTIVE'
                 AND membership.role_code IN ('platform_admin', 'internal_planner',
                    'agency_admin', 'agency_campaign_user'))
           OR NOT EXISTS (SELECT 1 FROM commercial.memberships membership
               WHERE membership.tenant_id = NEW.tenant_id
                 AND membership.user_id = NEW.approver_user_id
                 AND membership.status_code = 'ACTIVE'
                 AND membership.role_code IN ('platform_admin', 'internal_planner',
                    'advertiser_admin', 'advertiser_approver')) THEN
            RAISE EXCEPTION 'measurement report source is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.tenant_id, NEW.campaign_id, NEW.version_no,
        NEW.agent_run_id, NEW.campaign_version, NEW.measurement_plan_json,
        NEW.evidence_versions_json, NEW.metric_ids, NEW.interpretation_json,
        NEW.limitations_json, NEW.input_hash, NEW.output_hash,
        NEW.agent_contract_version, NEW.prompt_version, NEW.provider_code,
        NEW.model_code, NEW.tool_calls, NEW.incremental_cost_minor,
        NEW.output_validated, NEW.status_collection_code,
        NEW.approver_user_id, NEW.generated_by, NEW.generated_at_utc)
       IS DISTINCT FROM
       (OLD.id, OLD.tenant_id, OLD.campaign_id, OLD.version_no,
        OLD.agent_run_id, OLD.campaign_version, OLD.measurement_plan_json,
        OLD.evidence_versions_json, OLD.metric_ids, OLD.interpretation_json,
        OLD.limitations_json, OLD.input_hash, OLD.output_hash,
        OLD.agent_contract_version, OLD.prompt_version, OLD.provider_code,
        OLD.model_code, OLD.tool_calls, OLD.incremental_cost_minor,
        OLD.output_validated, OLD.status_collection_code,
        OLD.approver_user_id, OLD.generated_by, OLD.generated_at_utc)
       OR OLD.status_code <> 'REVIEW_REQUIRED'
       OR NEW.status_code NOT IN ('APPROVED', 'REJECTED')
       OR NEW.tenant_id <> commercial.current_tenant_id()
       OR NEW.reviewed_by <> commercial.current_user_id()
       OR NEW.reviewed_by <> OLD.approver_user_id
       OR NEW.reviewed_by = OLD.generated_by
       OR NEW.reviewed_at_utc < OLD.generated_at_utc
       OR NEW.updated_at_utc <> NEW.reviewed_at_utc
       OR NEW.version <> OLD.version + 1
       OR NOT EXISTS (SELECT 1 FROM commercial.memberships membership
           WHERE membership.tenant_id = OLD.tenant_id
             AND membership.user_id = NEW.reviewed_by
             AND membership.status_code = 'ACTIVE'
             AND membership.role_code IN ('platform_admin', 'internal_planner',
                'advertiser_admin', 'advertiser_approver')) THEN
        RAISE EXCEPTION 'measurement report review is invalid';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_payment_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'payments cannot be deleted'; END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT status_code, proposal_version_id, proposal_option_id,
            purchase_order_id, total_minor, currency_code INTO expected
        FROM commercial.invoices
        WHERE tenant_id = NEW.tenant_id AND id = NEW.invoice_id;
        IF NOT FOUND OR expected.status_code <> 'ISSUED'
           OR NEW.status_code <> 'PENDING'
           OR NEW.started_by <> commercial.current_user_id()
           OR NEW.method_code <> 'MANUAL_EFT'
           OR (NEW.proposal_version_id, NEW.proposal_option_id,
               NEW.purchase_order_id, NEW.amount_minor, NEW.currency_code)
              IS DISTINCT FROM
              (expected.proposal_version_id, expected.proposal_option_id,
               expected.purchase_order_id, expected.total_minor, expected.currency_code) THEN
            RAISE EXCEPTION 'payment does not reconcile to issued invoice';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.tenant_id, NEW.proposal_version_id, NEW.proposal_option_id,
        NEW.purchase_order_id, NEW.invoice_id, NEW.method_collection_code,
        NEW.method_code, NEW.amount_minor, NEW.currency_collection_code,
        NEW.currency_code, NEW.started_by, NEW.started_at_utc) IS DISTINCT FROM
       (OLD.id, OLD.tenant_id, OLD.proposal_version_id, OLD.proposal_option_id,
        OLD.purchase_order_id, OLD.invoice_id, OLD.method_collection_code,
        OLD.method_code, OLD.amount_minor, OLD.currency_collection_code,
        OLD.currency_code, OLD.started_by, OLD.started_at_utc) THEN
        RAISE EXCEPTION 'payment commercial snapshot is immutable';
    END IF;
    IF OLD.status_code <> 'PENDING' OR NEW.status_code <> 'CONFIRMED'
       OR NEW.reconciled_by <> commercial.current_user_id()
       OR NEW.reconciled_by = OLD.started_by
       OR NEW.version <> OLD.version + 1 OR NEW.updated_at_utc < OLD.updated_at_utc THEN
        RAISE EXCEPTION 'invalid payment reconciliation';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_performance_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE campaign_row record;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'performance evidence cannot be deleted';
    END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT campaign.status_code, campaign.completed_at_utc
        INTO campaign_row
        FROM commercial.campaigns campaign
        WHERE campaign.tenant_id = NEW.tenant_id
          AND campaign.id = NEW.campaign_id;
        IF NOT FOUND OR campaign_row.status_code <> 'COMPLETED'
           OR NEW.tenant_id <> commercial.current_tenant_id()
           OR NEW.created_by <> commercial.current_user_id()
           OR NEW.reviewer_user_id = NEW.created_by
           OR NEW.status_code <> 'DRAFT' OR NEW.version <> 0
           OR NEW.updated_at_utc <> NEW.created_at_utc
           OR NEW.captured_at_utc < campaign_row.completed_at_utc
           OR NEW.captured_at_utc > NEW.created_at_utc
           OR NEW.protected_object_key <>
                'protected/' || replace(NEW.tenant_id::text, '-', '') ||
                '/campaigns/' || replace(NEW.campaign_id::text, '-', '') ||
                '/performance/' || replace(NEW.id::text, '-', '') || '/' ||
                NEW.content_sha256
           OR jsonb_array_length(NEW.limitations_json) > 20
           OR EXISTS (
               SELECT 1 FROM jsonb_array_elements(NEW.limitations_json) item
               WHERE jsonb_typeof(item) <> 'string'
                  OR btrim(item #>> '{}') = ''
                  OR length(item #>> '{}') > 500)
           OR NOT EXISTS (
               SELECT 1 FROM commercial.memberships membership
               WHERE membership.tenant_id = NEW.tenant_id
                 AND membership.user_id = NEW.created_by
                 AND membership.status_code = 'ACTIVE'
                 AND membership.role_code IN (
                    'platform_admin', 'internal_planner',
                    'agency_admin', 'agency_campaign_user'))
           OR NOT EXISTS (
               SELECT 1 FROM commercial.memberships membership
               WHERE membership.tenant_id = NEW.tenant_id
                 AND membership.user_id = NEW.reviewer_user_id
                 AND membership.status_code = 'ACTIVE'
                 AND membership.role_code IN (
                    'platform_admin', 'internal_planner',
                    'advertiser_admin', 'advertiser_approver'))
           OR NOT EXISTS (
               SELECT 1 FROM commercial.delivery_proofs proof
               WHERE proof.buyer_tenant_id = NEW.tenant_id
                 AND proof.campaign_id = NEW.campaign_id
                 AND proof.status_code = 'APPROVED') THEN
            RAISE EXCEPTION 'performance evidence source is invalid';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.tenant_id, NEW.campaign_id, NEW.source_reference,
        NEW.file_name, NEW.media_type, NEW.size_bytes, NEW.content_sha256,
        NEW.signature_validated, NEW.malware_scan_status_collection_code,
        NEW.malware_scan_status_code, NEW.protected_object_key,
        NEW.captured_at_utc, NEW.methodology, NEW.limitations_json,
        NEW.quality_status_collection_code, NEW.quality_status_code,
        NEW.status_collection_code, NEW.reviewer_user_id,
        NEW.created_by, NEW.created_at_utc) IS DISTINCT FROM
       (OLD.id, OLD.tenant_id, OLD.campaign_id, OLD.source_reference,
        OLD.file_name, OLD.media_type, OLD.size_bytes, OLD.content_sha256,
        OLD.signature_validated, OLD.malware_scan_status_collection_code,
        OLD.malware_scan_status_code, OLD.protected_object_key,
        OLD.captured_at_utc, OLD.methodology, OLD.limitations_json,
        OLD.quality_status_collection_code, OLD.quality_status_code,
        OLD.status_collection_code, OLD.reviewer_user_id,
        OLD.created_by, OLD.created_at_utc) THEN
        RAISE EXCEPTION 'performance evidence source is immutable';
    END IF;
    IF OLD.status_code = 'DRAFT' AND NEW.status_code = 'SUBMITTED' THEN
        IF NEW.tenant_id <> commercial.current_tenant_id()
           OR NEW.submitted_by <> commercial.current_user_id()
           OR NEW.submitted_by <> OLD.created_by
           OR NEW.submitted_at_utc < OLD.created_at_utc
           OR NEW.updated_at_utc <> NEW.submitted_at_utc
           OR NEW.version <> 1
           OR NOT EXISTS (
               SELECT 1 FROM commercial.performance_metrics metric
               WHERE metric.tenant_id = OLD.tenant_id
                 AND metric.evidence_set_id = OLD.id) THEN
            RAISE EXCEPTION 'performance evidence facts are incomplete';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status_code = 'SUBMITTED'
       AND NEW.status_code IN ('APPROVED', 'REJECTED') THEN
        IF NEW.tenant_id <> commercial.current_tenant_id()
           OR NEW.reviewed_by <> commercial.current_user_id()
           OR NEW.reviewed_by <> OLD.reviewer_user_id
           OR NEW.reviewed_by = OLD.submitted_by
           OR NEW.reviewed_at_utc < OLD.submitted_at_utc
           OR NEW.updated_at_utc <> NEW.reviewed_at_utc
           OR NEW.version <> OLD.version + 1
           OR (NEW.submitted_by, NEW.submitted_at_utc) IS DISTINCT FROM
              (OLD.submitted_by, OLD.submitted_at_utc)
           OR (NEW.status_code = 'APPROVED'
               AND OLD.quality_status_code = 'UNUSABLE')
           OR NOT EXISTS (
               SELECT 1 FROM commercial.memberships membership
               WHERE membership.tenant_id = OLD.tenant_id
                 AND membership.user_id = NEW.reviewed_by
                 AND membership.status_code = 'ACTIVE'
                 AND membership.role_code IN (
                    'platform_admin', 'internal_planner',
                    'advertiser_admin', 'advertiser_approver')) THEN
            RAISE EXCEPTION 'performance evidence review is invalid';
        END IF;
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'performance evidence transition is invalid';
END;
$$;
CREATE FUNCTION commercial.enforce_performance_metric() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP <> 'INSERT' THEN
        RAISE EXCEPTION 'performance metrics are immutable';
    END IF;
    SELECT evidence.status_code, evidence.created_by,
        campaign.start_date, campaign.end_date
    INTO expected
    FROM commercial.performance_evidence_sets evidence
    JOIN commercial.campaigns campaign
      ON campaign.tenant_id = evidence.tenant_id
     AND campaign.id = evidence.campaign_id
    WHERE evidence.tenant_id = NEW.tenant_id
      AND evidence.id = NEW.evidence_set_id
      AND evidence.campaign_id = NEW.campaign_id;
    IF NOT FOUND OR expected.status_code <> 'DRAFT'
       OR NEW.tenant_id <> commercial.current_tenant_id()
       OR NEW.created_by <> commercial.current_user_id()
       OR NEW.created_by <> expected.created_by
       OR NEW.period_start < expected.start_date
       OR NEW.period_end > expected.end_date THEN
        RAISE EXCEPTION 'performance metric source is invalid';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.enforce_purchase_order_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected record;
BEGIN
    IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'purchase orders cannot be deleted'; END IF;
    IF TG_OP = 'INSERT' THEN
        SELECT proposal.status_code AS proposal_status,
            decision.decision_code, decision.option_id,
            option.plan_version_id, option.budget_minor,
            option.currency_code, plan.status_code AS plan_status,
            plan.total_minor INTO expected
        FROM commercial.proposal_versions proposal
        JOIN commercial.proposal_decisions decision
          ON decision.tenant_id = proposal.tenant_id
         AND decision.proposal_version_id = proposal.id
        JOIN commercial.proposal_options option
          ON option.tenant_id = decision.tenant_id AND option.id = decision.option_id
        JOIN commercial.media_plan_versions plan
          ON plan.tenant_id = option.tenant_id AND plan.id = option.plan_version_id
        WHERE proposal.tenant_id = NEW.tenant_id
          AND proposal.id = NEW.proposal_version_id
          AND option.id = NEW.proposal_option_id
          AND decision.id = NEW.proposal_decision_id;
        IF NOT FOUND OR expected.proposal_status <> 'SELECTED'
           OR expected.decision_code <> 'SELECTED'
           OR expected.plan_status <> 'APPROVED'
           OR (NEW.proposal_option_id, NEW.plan_version_id,
               NEW.amount_minor, NEW.currency_code)
              IS DISTINCT FROM
              (expected.option_id, expected.plan_version_id,
               expected.total_minor, expected.currency_code)
           OR expected.budget_minor <> expected.total_minor
           OR NEW.status_code <> 'SUBMITTED'
           OR NEW.submitted_by <> commercial.current_user_id() THEN
            RAISE EXCEPTION 'purchase order does not reconcile to selected option';
        END IF;
        RETURN NEW;
    END IF;
    IF (NEW.id, NEW.tenant_id, NEW.proposal_version_id, NEW.proposal_option_id,
        NEW.proposal_decision_id, NEW.plan_version_id, NEW.po_number, NEW.object_key,
        NEW.content_sha256, NEW.media_type, NEW.size_bytes, NEW.amount_minor,
        NEW.currency_collection_code, NEW.currency_code, NEW.submitted_by,
        NEW.submitted_at_utc) IS DISTINCT FROM
       (OLD.id, OLD.tenant_id, OLD.proposal_version_id, OLD.proposal_option_id,
        OLD.proposal_decision_id, OLD.plan_version_id, OLD.po_number, OLD.object_key,
        OLD.content_sha256, OLD.media_type, OLD.size_bytes, OLD.amount_minor,
        OLD.currency_collection_code, OLD.currency_code, OLD.submitted_by,
        OLD.submitted_at_utc) THEN
        RAISE EXCEPTION 'purchase order snapshot is immutable';
    END IF;
    IF OLD.status_code <> 'SUBMITTED' OR NEW.status_code <> 'APPROVED'
       OR NEW.approved_by <> commercial.current_user_id()
       OR NEW.approved_by = OLD.submitted_by
       OR NEW.version <> OLD.version + 1 OR NEW.updated_at_utc < OLD.updated_at_utc THEN
        RAISE EXCEPTION 'invalid purchase order approval';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.fail_outbox_event(p_event_id uuid, p_claim_token uuid, p_terminal boolean, p_failure_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE
    tenant_context uuid := commercial.current_tenant_id();
    failed_at_utc timestamptz := pg_catalog.statement_timestamp();
    changed_count integer;
BEGIN
    IF tenant_context IS NULL THEN
        RAISE EXCEPTION 'outbox dispatch requires tenant context'
            USING ERRCODE = '42501';
    END IF;
    IF p_terminal IS NULL
       OR p_failure_code IS NULL
       OR p_failure_code !~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,99}$' THEN
        RAISE EXCEPTION 'outbox failure evidence is invalid'
            USING ERRCODE = '22023';
    END IF;
    UPDATE commercial.outbox_messages event
    SET last_failure_code = p_failure_code,
        last_failure_at_utc = failed_at_utc,
        dead_lettered_at_utc = CASE
            WHEN p_terminal OR event.attempts >= 4
            THEN failed_at_utc ELSE NULL END,
        next_attempt_at_utc = CASE
            WHEN p_terminal OR event.attempts >= 4 THEN NULL
            WHEN event.attempts = 1
                THEN failed_at_utc + INTERVAL '30 seconds'
            WHEN event.attempts = 2
                THEN failed_at_utc + INTERVAL '2 minutes'
            WHEN event.attempts = 3
                THEN failed_at_utc + INTERVAL '10 minutes'
            ELSE NULL END,
        claim_token = NULL,
        lease_owner = NULL,
        lease_expires_at_utc = NULL,
        attempt_started_at_utc = NULL
    WHERE event.id = p_event_id
      AND event.tenant_id = tenant_context
      AND event.claim_token = p_claim_token
      AND event.published_at_utc IS NULL
      AND event.dead_lettered_at_utc IS NULL
      AND event.lease_expires_at_utc > failed_at_utc;
    GET DIAGNOSTICS changed_count = ROW_COUNT;
    RETURN changed_count = 1;
END;
$_$;
CREATE FUNCTION commercial.heartbeat_email_work(p_claim_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    UPDATE commercial.email_worker_claims claim
    SET lease_expires_at_utc = pg_catalog.statement_timestamp()
        + pg_catalog.make_interval(secs => p_lease_seconds)
    WHERE claim.claim_token = p_claim_token
      AND claim.dead_lettered_at_utc IS NULL
      AND claim.lease_expires_at_utc > pg_catalog.statement_timestamp()
      AND p_lease_seconds BETWEEN 30 AND 600
    RETURNING TRUE
$$;
CREATE FUNCTION commercial.heartbeat_inventory_extraction_attempt(p_claim_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    UPDATE commercial.inventory_extraction_attempts attempt
    SET worker_lease_expires_at_utc = pg_catalog.statement_timestamp()
        + pg_catalog.make_interval(secs => p_lease_seconds)
    WHERE attempt.worker_lease_token = p_claim_token
      AND attempt.worker_lease_expires_at_utc > pg_catalog.statement_timestamp()
      AND p_lease_seconds BETWEEN 30 AND 600
    RETURNING TRUE
$$;
CREATE FUNCTION commercial.heartbeat_outbox_event(p_event_id uuid, p_claim_token uuid, p_lease_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    tenant_context uuid := commercial.current_tenant_id();
    heartbeat_at_utc timestamptz := pg_catalog.statement_timestamp();
    lease_until_utc timestamptz;
    changed_count integer;
BEGIN
    IF tenant_context IS NULL THEN
        RAISE EXCEPTION 'outbox dispatch requires tenant context'
            USING ERRCODE = '42501';
    END IF;
    IF p_lease_seconds IS NULL
       OR p_lease_seconds < 5
       OR p_lease_seconds > 300 THEN
        RAISE EXCEPTION 'outbox heartbeat timing is invalid'
            USING ERRCODE = '22023';
    END IF;
    lease_until_utc := heartbeat_at_utc
        + pg_catalog.make_interval(secs => p_lease_seconds);
    UPDATE commercial.outbox_messages event
    SET lease_expires_at_utc = lease_until_utc
    WHERE event.id = p_event_id
      AND event.tenant_id = tenant_context
      AND event.claim_token = p_claim_token
      AND event.published_at_utc IS NULL
      AND event.dead_lettered_at_utc IS NULL
      AND event.lease_expires_at_utc > heartbeat_at_utc
      AND lease_until_utc > event.lease_expires_at_utc;
    GET DIAGNOSTICS changed_count = ROW_COUNT;
    RETURN changed_count = 1;
END;
$$;
CREATE FUNCTION commercial.install_outbox_claim(p_event_id uuid, p_tenant_id uuid, p_worker_id uuid, p_claimed_at_utc timestamp with time zone, p_lease_until_utc timestamp with time zone, p_lease_expired boolean) RETURNS void
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
    UPDATE commercial.outbox_messages event
    SET last_failure_code = CASE WHEN p_lease_expired
            THEN 'OUTBOX_LEASE_EXPIRED' ELSE event.last_failure_code END,
        last_failure_at_utc = CASE WHEN p_lease_expired
            THEN p_claimed_at_utc ELSE event.last_failure_at_utc END,
        dead_lettered_at_utc = NULL,
        claim_token = pg_catalog.gen_random_uuid(),
        lease_owner = p_worker_id,
        lease_expires_at_utc = p_lease_until_utc,
        attempt_started_at_utc = p_claimed_at_utc,
        next_attempt_at_utc = NULL,
        attempts = event.attempts + 1
    WHERE event.id = p_event_id AND event.tenant_id = p_tenant_id
$$;
CREATE FUNCTION commercial.inventory_asset_rights_valid(p_asset_id uuid, p_scope character varying, p_territory character varying, p_today date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM commercial.inventory_assets asset
        JOIN LATERAL (
            SELECT review.*
            FROM commercial.inventory_asset_rights_reviews review
            WHERE review.tenant_id = asset.tenant_id
              AND review.asset_id = asset.id
            ORDER BY review.asset_version DESC LIMIT 1) rights ON TRUE
        WHERE asset.id = p_asset_id
          AND rights.rights_status_code = 'APPROVED'
          AND rights.scope_codes ? p_scope
          AND rights.territory_code = p_territory
          AND rights.effective_on <= p_today
          AND (rights.until_revoked OR rights.licensed_until >= p_today)
          AND (asset.tenant_id = commercial.current_tenant_id()
            OR EXISTS (
                SELECT 1
                FROM commercial.marketplace_listing_versions snapshot
                JOIN commercial.marketplace_listings listing
                  ON listing.supplier_tenant_id = snapshot.supplier_tenant_id
                 AND listing.current_version_id = snapshot.id
                WHERE snapshot.supplier_tenant_id = asset.tenant_id
                  AND snapshot.logo_asset_id = asset.id
                  AND listing.status_code = 'PUBLISHED')));
$$;
CREATE FUNCTION commercial.inventory_coverage_qualifies(p_coverage public.geometry, p_target public.geometry, p_threshold numeric) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
    target_area double precision;
BEGIN
    IF p_coverage IS NULL OR p_target IS NULL OR
        NOT public.ST_IsValid(p_coverage) OR NOT public.ST_IsValid(p_target) THEN
        RETURN false;
    END IF;
    target_area := public.ST_Area(p_target::geography);
    IF target_area <= 0 THEN RETURN false; END IF;
    RETURN public.ST_Area(
        public.ST_Intersection(p_coverage, p_target)::geography) / target_area
        >= COALESCE(p_threshold, 0.5);
EXCEPTION WHEN OTHERS THEN
    RETURN false;
END;
$$;
CREATE FUNCTION commercial.lock_next_outbox_event(p_tenant_id uuid, p_claimed_at_utc timestamp with time zone) RETURNS TABLE(event_id uuid, attempts integer, lease_expired boolean)
    LANGUAGE sql
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT candidate.id, candidate.attempts,
        candidate.claim_token IS NOT NULL
            AND candidate.lease_expires_at_utc <= p_claimed_at_utc
    FROM commercial.outbox_messages candidate
    WHERE candidate.tenant_id = p_tenant_id
      AND candidate.published_at_utc IS NULL
      AND candidate.dead_lettered_at_utc IS NULL
      AND ((candidate.claim_token IS NULL
            AND (candidate.next_attempt_at_utc IS NULL
                OR candidate.next_attempt_at_utc <= p_claimed_at_utc))
           OR candidate.lease_expires_at_utc <= p_claimed_at_utc)
    ORDER BY candidate.occurred_at_utc, candidate.id
    FOR UPDATE SKIP LOCKED
    LIMIT 1
$$;
CREATE FUNCTION commercial.marketplace_inventory_unavailable_periods(p_supplier_tenant_id uuid, p_product_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'start', exception.starts_on, 'end', exception.ends_on,
        'reason', exception.exception_type_code)
        ORDER BY exception.starts_on, exception.ends_on, exception.id), '[]')
    FROM commercial.inventory_availability_exceptions exception
    WHERE exception.tenant_id = p_supplier_tenant_id
      AND exception.product_id = p_product_id
      AND (p_supplier_tenant_id = commercial.current_tenant_id()
        OR EXISTS (
            SELECT 1 FROM commercial.marketplace_listings listing
            WHERE listing.supplier_tenant_id = p_supplier_tenant_id
              AND listing.product_id = p_product_id
              AND listing.status_code = 'PUBLISHED'));
$$;
CREATE FUNCTION commercial.measurement_report_source(requested_campaign_id uuid, requested_approver_user_id uuid) RETURNS TABLE(tenant_id uuid, campaign_id uuid, opportunity_id uuid, campaign_version bigint, measurement_plan_json jsonb, approver_user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT campaign.tenant_id, campaign.id, brief.opportunity_id,
        campaign.version, campaign.measurement_plan_json, reviewer.user_id
    FROM commercial.campaigns campaign
    JOIN commercial.campaign_briefs brief
      ON brief.tenant_id = campaign.tenant_id AND brief.id = campaign.brief_id
    JOIN commercial.memberships generator
      ON generator.tenant_id = campaign.tenant_id
     AND generator.user_id = commercial.current_user_id()
     AND generator.status_code = 'ACTIVE'
     AND generator.role_code IN (
        'platform_admin', 'internal_planner', 'agency_admin',
        'agency_campaign_user')
    JOIN commercial.memberships reviewer
      ON reviewer.tenant_id = campaign.tenant_id
     AND reviewer.user_id = requested_approver_user_id
     AND reviewer.status_code = 'ACTIVE'
     AND reviewer.role_code IN (
        'platform_admin', 'internal_planner',
        'advertiser_admin', 'advertiser_approver')
    WHERE campaign.id = requested_campaign_id
      AND campaign.tenant_id = commercial.current_tenant_id()
      AND campaign.status_code = 'COMPLETED'
      AND jsonb_typeof(campaign.measurement_plan_json) = 'array'
      AND jsonb_array_length(campaign.measurement_plan_json) > 0
      AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(campaign.measurement_plan_json) item
          WHERE jsonb_typeof(item) <> 'string' OR btrim(item #>> '{}') = '')
      AND requested_approver_user_id <> commercial.current_user_id()
      AND EXISTS (SELECT 1 FROM commercial.delivery_proofs proof
          WHERE proof.buyer_tenant_id = campaign.tenant_id
            AND proof.campaign_id = campaign.id
            AND proof.status_code = 'APPROVED')
      AND EXISTS (SELECT 1 FROM commercial.performance_evidence_sets evidence
          JOIN commercial.performance_metrics metric
            ON metric.tenant_id = evidence.tenant_id
           AND metric.evidence_set_id = evidence.id
          WHERE evidence.tenant_id = campaign.tenant_id
            AND evidence.campaign_id = campaign.id
            AND evidence.status_code = 'APPROVED')
      AND NOT EXISTS (SELECT 1 FROM commercial.measurement_report_versions report
          WHERE report.tenant_id = campaign.tenant_id
            AND report.campaign_id = campaign.id
            AND report.status_code = 'REVIEW_REQUIRED');
$$;
CREATE FUNCTION commercial.next_agent_run_due() RETURNS timestamp with time zone
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT GREATEST(min(due_at), statement_timestamp())
    FROM (
        (SELECT COALESCE(next_attempt_at_utc, '-infinity'::timestamptz) AS due_at
         FROM commercial.agent_runs WHERE status_code = 'QUEUED'
         ORDER BY COALESCE(next_attempt_at_utc, '-infinity'::timestamptz) LIMIT 1)
        UNION ALL
        (SELECT GREATEST(lease_expires_at_utc,
            COALESCE(next_attempt_at_utc, '-infinity'::timestamptz)) AS due_at
         FROM commercial.agent_runs
         WHERE status_code = 'RUNNING' AND lease_expires_at_utc IS NOT NULL
         ORDER BY GREATEST(lease_expires_at_utc,
            COALESCE(next_attempt_at_utc, '-infinity'::timestamptz)) LIMIT 1)
    ) deadlines
    HAVING count(*) > 0;
$$;
CREATE FUNCTION commercial.next_inventory_extraction_due(p_max_concurrency integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE result timestamptz;
BEGIN
    IF p_max_concurrency IS NULL OR p_max_concurrency NOT BETWEEN 1 AND 4 THEN
        RAISE EXCEPTION 'Invalid extraction concurrency' USING ERRCODE = '22023';
    END IF;
    -- Eligibility mirrors migration 046's authoritative claim contract.
    WITH active AS (
        SELECT count(*) AS value FROM commercial.inventory_extraction_attempts item
        WHERE item.extracted_artifact_id IS NULL
          AND (item.status_code IN ('SUBMITTING', 'RUNNING', 'FAILED_RETRYABLE')
               OR (item.status_code = 'PENDING'
                   AND item.worker_lease_expires_at_utc > statement_timestamp()))
    )
    SELECT min(GREATEST(
        COALESCE(attempt.worker_lease_expires_at_utc, statement_timestamp()),
        CASE attempt.status_code
            WHEN 'RUNNING' THEN COALESCE(
                attempt.last_polled_at_utc + interval '10 seconds', statement_timestamp())
            WHEN 'FAILED_RETRYABLE' THEN attempt.updated_at_utc + interval '30 seconds'
            ELSE statement_timestamp()
        END)) INTO result
    FROM commercial.inventory_extraction_attempts attempt
    WHERE attempt.status_code IN ('PENDING', 'SUBMITTING', 'RUNNING', 'FAILED_RETRYABLE')
      AND attempt.extracted_artifact_id IS NULL
      AND (attempt.status_code <> 'PENDING' OR (SELECT value FROM active) < p_max_concurrency);
    RETURN result;
END;
$$;
CREATE FUNCTION commercial.next_outbox_tenant() RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT event.tenant_id
    FROM commercial.outbox_messages event
    WHERE event.published_at_utc IS NULL
      AND event.dead_lettered_at_utc IS NULL
      AND (
        (event.claim_token IS NULL AND
            (event.next_attempt_at_utc IS NULL OR
             event.next_attempt_at_utc <= pg_catalog.statement_timestamp()))
        OR event.lease_expires_at_utc <= pg_catalog.statement_timestamp())
    ORDER BY event.occurred_at_utc, event.id
    LIMIT 1
$$;
CREATE FUNCTION commercial.notify_agent_run_schedule() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
BEGIN
    IF NEW.status_code NOT IN ('QUEUED', 'RUNNING') THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' THEN
        -- Step checkpoints, unrelated changes and ordinary lease extensions are silent.
        IF NEW.status_code IS NOT DISTINCT FROM OLD.status_code
           AND NEW.next_attempt_at_utc IS NOT DISTINCT FROM OLD.next_attempt_at_utc
           AND NOT (NEW.status_code = 'RUNNING'
               AND NEW.lease_expires_at_utc IS NOT NULL
               AND (OLD.lease_expires_at_utc IS NULL
                    OR NEW.lease_expires_at_utc < OLD.lease_expires_at_utc))
        THEN RETURN NEW; END IF;
    END IF;
    -- Transactional, coalescible wake only: no tenant, run or business payload.
    PERFORM pg_notify('advertified_agent_run', '');
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.performance_evidence_source(requested_campaign_id uuid, requested_reviewer_user_id uuid) RETURNS TABLE(tenant_id uuid, campaign_id uuid, campaign_start date, campaign_end date, completed_at_utc timestamp with time zone, reviewer_user_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT campaign.tenant_id, campaign.id,
        campaign.start_date, campaign.end_date,
        campaign.completed_at_utc, reviewer.user_id
    FROM commercial.campaigns campaign
    JOIN commercial.memberships submitter
      ON submitter.tenant_id = campaign.tenant_id
     AND submitter.user_id = commercial.current_user_id()
     AND submitter.status_code = 'ACTIVE'
     AND submitter.role_code IN (
        'platform_admin', 'internal_planner', 'agency_admin',
        'agency_campaign_user')
    JOIN commercial.memberships reviewer
      ON reviewer.tenant_id = campaign.tenant_id
     AND reviewer.user_id = requested_reviewer_user_id
     AND reviewer.status_code = 'ACTIVE'
     AND reviewer.role_code IN (
        'platform_admin', 'internal_planner',
        'advertiser_admin', 'advertiser_approver')
    WHERE campaign.id = requested_campaign_id
      AND campaign.tenant_id = commercial.current_tenant_id()
      AND campaign.status_code = 'COMPLETED'
      AND campaign.completed_at_utc IS NOT NULL
      AND requested_reviewer_user_id <> commercial.current_user_id()
      AND EXISTS (
          SELECT 1 FROM commercial.delivery_proofs proof
          WHERE proof.buyer_tenant_id = campaign.tenant_id
            AND proof.campaign_id = campaign.id
            AND proof.status_code = 'APPROVED');
$$;
CREATE FUNCTION commercial.protect_outbox_event_truth() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'outbox events cannot be deleted';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.causation_id IS DISTINCT FROM OLD.causation_id
       OR NEW.correlation_id IS DISTINCT FROM OLD.correlation_id
       OR NEW.event_type_code IS DISTINCT FROM OLD.event_type_code
       OR NEW.aggregate_type_code IS DISTINCT FROM OLD.aggregate_type_code
       OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
       OR NEW.aggregate_version IS DISTINCT FROM OLD.aggregate_version
       OR NEW.payload_json IS DISTINCT FROM OLD.payload_json
       OR NEW.occurred_at_utc IS DISTINCT FROM OLD.occurred_at_utc THEN
        RAISE EXCEPTION 'outbox event truth is immutable';
    END IF;
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.read_approved_inventory_asset(p_asset_id uuid, p_today date) RETURNS TABLE(object_key character varying, media_type character varying, content_hash character)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
    SELECT asset.object_key, asset.media_type, asset.content_hash
    FROM commercial.inventory_assets asset
    WHERE asset.id = p_asset_id
      AND commercial.inventory_asset_rights_valid(
          asset.id,
          CASE WHEN asset.tenant_id = commercial.current_tenant_id()
              THEN 'INTERNAL_PLANNING'
              ELSE 'MARKETPLACE_DISPLAY' END,
          'ZA', p_today);
$$;
CREATE FUNCTION commercial.register_supplier_inventory_replacement_impacts(p_inventory_tenant_id uuid, p_supplier_id uuid, p_old_release_id uuid, p_replacement_release_id uuid, p_actor_id uuid, p_detected_at_utc timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
DECLARE
    inserted_count integer;
BEGIN
    IF p_inventory_tenant_id IS NULL OR
        p_inventory_tenant_id IS DISTINCT FROM commercial.current_tenant_id() THEN
        RAISE EXCEPTION 'Inventory tenant does not match the current session';
    END IF;
    IF p_actor_id IS NULL OR
        p_actor_id IS DISTINCT FROM commercial.current_user_id() THEN
        RAISE EXCEPTION 'Actor does not match the current session';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM commercial.inventory_suppliers supplier
        WHERE supplier.tenant_id = p_inventory_tenant_id
          AND supplier.id = p_supplier_id) THEN
        RAISE EXCEPTION 'Supplier does not belong to the inventory tenant';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM commercial.inventory_supplier_releases release
        WHERE release.tenant_id = p_inventory_tenant_id
          AND release.supplier_id = p_supplier_id
          AND release.id = p_old_release_id
          AND release.status_code = 'SUPERSEDED') THEN
        RAISE EXCEPTION 'Previous release is not a superseded supplier release';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM commercial.inventory_supplier_releases release
        WHERE release.tenant_id = p_inventory_tenant_id
          AND release.supplier_id = p_supplier_id
          AND release.id = p_replacement_release_id
          AND release.supersedes_release_id = p_old_release_id
          AND release.status_code = 'CURRENT') THEN
        RAISE EXCEPTION 'Replacement release lineage is invalid';
    END IF;
    INSERT INTO commercial.proposal_inventory_impacts (
        id, tenant_id, proposal_version_id, proposal_option_id,
        media_plan_line_id, inventory_tenant_id, supplier_id,
        old_release_id, replacement_release_id,
        old_product_id, old_product_version_id, old_rate_id,
        old_availability_id, replacement_product_id,
        replacement_product_version_id, replacement_rate_id,
        replacement_availability_id, impact_type_code,
        status_code, comparison_json, detected_at_utc, version)
    SELECT gen_random_uuid(), proposal.tenant_id, proposal.id, option.id,
        line.id, line.inventory_tenant_id, p_supplier_id,
        p_old_release_id, p_replacement_release_id,
        line.inventory_product_id, line.product_version_id,
        line.rate_id, line.availability_id,
        replacement.id, replacement.current_version_id,
        replacement_rate.id, replacement_availability.id,
        'SUPPLIER_RELEASE_SUPERSEDED', 'OPEN',
        jsonb_build_object(
            'oldProductCode', old_product.supplier_product_code,
            'oldProductName', line.product_name,
            'oldGeography', line.geography,
            'oldRateMinor', old_rate.amount_minor,
            'newProductFound', replacement.id IS NOT NULL,
            'newProductName', replacement_version.name,
            'newGeography', replacement_version.geography,
            'newRateMinor', replacement_rate.amount_minor,
            'rateChanged', replacement_rate.amount_minor IS DISTINCT FROM
                old_rate.amount_minor,
            'geographyChanged', replacement_version.geography IS DISTINCT FROM
                line.geography),
        p_detected_at_utc, 1
    FROM commercial.proposal_versions proposal
    JOIN commercial.proposal_options option
      ON option.tenant_id = proposal.tenant_id
     AND option.proposal_version_id = proposal.id
    JOIN commercial.media_plan_lines line
      ON line.tenant_id = option.tenant_id
     AND line.plan_version_id = option.plan_version_id
    JOIN commercial.inventory_products old_product
      ON old_product.tenant_id = line.inventory_tenant_id
     AND old_product.id = line.inventory_product_id
    JOIN commercial.inventory_product_versions old_version
      ON old_version.tenant_id = line.inventory_tenant_id
     AND old_version.id = line.product_version_id
    JOIN commercial.inventory_rates old_rate
      ON old_rate.tenant_id = line.inventory_tenant_id
     AND old_rate.id = line.rate_id
    LEFT JOIN commercial.inventory_products replacement
      ON replacement.tenant_id = line.inventory_tenant_id
     AND replacement.supplier_id = p_supplier_id
     AND replacement.supplier_product_code =
            old_product.supplier_product_code
     AND replacement.current_release_id = p_replacement_release_id
     AND replacement.status_code = 'ACTIVE'
    LEFT JOIN commercial.inventory_product_versions replacement_version
      ON replacement_version.tenant_id = replacement.tenant_id
     AND replacement_version.id = replacement.current_version_id
    LEFT JOIN LATERAL (
        SELECT rate.*
        FROM commercial.inventory_rates rate
        WHERE rate.tenant_id = replacement_version.tenant_id
          AND rate.product_version_id = replacement_version.id
        ORDER BY rate.effective_from DESC NULLS LAST, rate.id DESC
        LIMIT 1) replacement_rate ON TRUE
    LEFT JOIN LATERAL (
        SELECT availability.*
        FROM commercial.inventory_availability availability
        WHERE availability.tenant_id = replacement_version.tenant_id
          AND availability.product_version_id = replacement_version.id
        ORDER BY availability.observed_at_utc DESC NULLS LAST,
            availability.id DESC
        LIMIT 1) replacement_availability ON TRUE
    WHERE line.inventory_tenant_id = p_inventory_tenant_id
      AND old_product.supplier_id = p_supplier_id
      AND old_version.inventory_release_id = p_old_release_id
      AND proposal.status_code IN (
          'DRAFT', 'IN_REVIEW', 'APPROVED', 'SENT', 'SELECTED')
      AND NOT EXISTS (
          SELECT 1
          FROM commercial.bookings booking
          WHERE booking.buyer_tenant_id = proposal.tenant_id
            AND booking.proposal_version_id = proposal.id
            AND booking.media_plan_line_id = line.id
            AND booking.status_code = 'CONFIRMED')
    ON CONFLICT (
        tenant_id, proposal_version_id, media_plan_line_id,
        replacement_release_id) DO NOTHING;
    GET DIAGNOSTICS inserted_count = ROW_COUNT;
    UPDATE commercial.proposal_versions proposal
    SET inventory_review_status_code = 'REVIEW_REQUIRED',
        version = version + 1
    WHERE proposal.inventory_review_status_code <> 'REVIEW_REQUIRED'
      AND EXISTS (
          SELECT 1
          FROM commercial.proposal_inventory_impacts impact
          WHERE impact.tenant_id = proposal.tenant_id
            AND impact.proposal_version_id = proposal.id
            AND impact.replacement_release_id = p_replacement_release_id
            AND impact.status_code = 'OPEN');
    INSERT INTO commercial.human_tasks (
        id, tenant_id, opportunity_id, task_type_code, status_code,
        title, why_it_matters, resource_type_code, resource_id,
        resource_version, assignee_user_id, action_schema_json,
        version, created_at_utc)
    SELECT gen_random_uuid(), proposal.tenant_id, brief.opportunity_id,
        'INVENTORY_SUPERSESSION_REVIEW', 'PENDING',
        'Review updated supplier inventory',
        'A supplier replaced inventory used by this proposal. Review affected lines before the proposal can continue.',
        'proposal_version', proposal.id, proposal.version,
        proposal.created_by,
        jsonb_build_object(
            'action', 'review_inventory_supersession',
            'replacementReleaseId', p_replacement_release_id),
        1, p_detected_at_utc
    FROM commercial.proposal_versions proposal
    JOIN commercial.campaign_briefs brief
      ON brief.tenant_id = proposal.tenant_id
     AND brief.id = proposal.brief_id
    WHERE EXISTS (
          SELECT 1
          FROM commercial.proposal_inventory_impacts impact
          WHERE impact.tenant_id = proposal.tenant_id
            AND impact.proposal_version_id = proposal.id
            AND impact.replacement_release_id = p_replacement_release_id
            AND impact.status_code = 'OPEN')
      AND NOT EXISTS (
          SELECT 1
          FROM commercial.human_tasks task
          WHERE task.tenant_id = proposal.tenant_id
            AND task.resource_id = proposal.id
            AND task.task_type_code =
                'INVENTORY_SUPERSESSION_REVIEW'
            AND task.status_code = 'PENDING');
    RETURN inserted_count;
END;
$$;
CREATE FUNCTION commercial.reject_final_artifact_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status_code = 'APPROVED' THEN
        RAISE EXCEPTION 'Approved commercial artefacts are immutable';
    END IF;
    RETURN NEW;
END
$$;
CREATE FUNCTION commercial.reject_immutable_record_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Immutable commercial records cannot be changed or deleted';
END
$$;
CREATE FUNCTION commercial.reject_submitted_brief_content_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.status_code <> 'DRAFT' THEN
            RAISE EXCEPTION 'Submitted BriefVersions are immutable';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status_code <> 'DRAFT' AND ROW(
        NEW.brief_id, NEW.base_version_id, NEW.source_id, NEW.version_no,
        NEW.business_problem, NEW.objective, NEW.audiences_json,
        NEW.geographies_json, NEW.timing, NEW.budget_minor,
        NEW.budget_unknown, NEW.currency_code, NEW.vat_status_code,
        NEW.fees_minor, NEW.constraints_json, NEW.measurement_json,
        NEW.facts_json, NEW.unknowns_json, NEW.assumptions_json,
        NEW.conflicts_json, NEW.evidence_bindings_json, NEW.created_by
    ) IS DISTINCT FROM ROW(
        OLD.brief_id, OLD.base_version_id, OLD.source_id, OLD.version_no,
        OLD.business_problem, OLD.objective, OLD.audiences_json,
        OLD.geographies_json, OLD.timing, OLD.budget_minor,
        OLD.budget_unknown, OLD.currency_code, OLD.vat_status_code,
        OLD.fees_minor, OLD.constraints_json, OLD.measurement_json,
        OLD.facts_json, OLD.unknowns_json, OLD.assumptions_json,
        OLD.conflicts_json, OLD.evidence_bindings_json, OLD.created_by
    ) THEN
        RAISE EXCEPTION 'Submitted BriefVersion content is immutable';
    END IF;
    RETURN NEW;
END
$$;
CREATE FUNCTION commercial.set_inventory_supplier_identity_key() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'commercial'
    AS $$
BEGIN
    NEW.identity_key := regexp_replace(
        lower(NEW.name), '[^a-z0-9]+', '', 'g');
    RETURN NEW;
END;
$$;
CREATE FUNCTION commercial.supplier_delivery_proof_requests() RETURNS TABLE(campaign_id uuid, booking_id uuid, supplier_name text, product_name text, channel_code text, geography text, flight_start date, flight_end date, proof_requested_at_utc timestamp with time zone, proof_request_reason text, latest_proof_id uuid, latest_proof_status text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT campaign.id,
        booking.id,
        booking.supplier_name,
        booking.product_name,
        booking.channel_code,
        booking.geography,
        booking.flight_start,
        booking.flight_end,
        campaign.proof_requested_at_utc,
        campaign.proof_request_reason,
        proof.id,
        proof.status_code
    FROM commercial.bookings booking
    JOIN commercial.campaigns campaign
      ON campaign.tenant_id = booking.buyer_tenant_id
     AND campaign.proposal_decision_id = booking.proposal_decision_id
     AND campaign.plan_version_id = booking.plan_version_id
    JOIN commercial.memberships membership
      ON membership.tenant_id = booking.supplier_tenant_id
     AND membership.user_id = commercial.current_user_id()
     AND membership.status_code = 'ACTIVE'
    JOIN commercial.users actor
      ON actor.id = membership.user_id
     AND actor.status_code = 'ACTIVE'
    JOIN commercial.tenants supplier_tenant
      ON supplier_tenant.id = membership.tenant_id
     AND supplier_tenant.status_code = 'ACTIVE'
    JOIN governance.master_data_items permission
      ON permission.collection_code = 'permissions'
     AND permission.code = 'delivery_proof_submit'
     AND permission.is_active
     AND permission.effective_from <= CURRENT_DATE
     AND (permission.effective_to IS NULL
          OR CURRENT_DATE < permission.effective_to)
     AND pg_catalog.jsonb_exists(
        permission.metadata_json -> 'roles', membership.role_code)
    LEFT JOIN LATERAL (
        SELECT candidate.id, candidate.status_code,
            candidate.submission_sequence
        FROM commercial.delivery_proofs candidate
        WHERE candidate.buyer_tenant_id = booking.buyer_tenant_id
          AND candidate.campaign_id = campaign.id
          AND candidate.booking_id = booking.id
          AND candidate.supplier_tenant_id = booking.supplier_tenant_id
        ORDER BY candidate.submission_sequence DESC
        LIMIT 1) proof ON true
    WHERE booking.supplier_tenant_id = commercial.current_tenant_id()
      AND booking.status_code = 'CONFIRMED'
      AND campaign.status_code = 'COMPLETED'
      AND campaign.proof_requested_by IS NOT NULL
      AND campaign.proof_requested_at_utc IS NOT NULL
      AND btrim(campaign.proof_request_reason) <> ''
    ORDER BY campaign.proof_requested_at_utc DESC, booking.id
    LIMIT 200;
$$;
CREATE FUNCTION commercial.try_parse_geojson(p_geojson text) RETURNS public.geometry
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
    RETURN public.ST_SetSRID(public.ST_GeomFromGeoJSON(p_geojson), 4326);
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;
CREATE FUNCTION commercial.valid_agent_usage_metadata(provider_code character varying, model_code character varying, incremental_cost_minor bigint, provider_request_id character varying) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT COALESCE(
        incremental_cost_minor >= 0 AND (
            (provider_code = 'deterministic'
                AND model_code = 'fixture-v1'
                AND incremental_cost_minor = 0
                AND provider_request_id IS NULL)
            OR
            (provider_code = 'bedrock'
                AND btrim(COALESCE(model_code, '')) <> ''
                AND model_code <> 'fixture-v1'
                AND btrim(COALESCE(provider_request_id, '')) <> '')
        ),
        FALSE);
$$;
CREATE FUNCTION governance.audit_master_data_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO governance.master_data_item_history
        (collection_code, item_code, operation, snapshot_json, changed_at_utc)
    VALUES
        (NEW.collection_code, NEW.code, TG_OP, to_jsonb(NEW), CURRENT_TIMESTAMP);
    RETURN NEW;
END
$$;
CREATE FUNCTION governance.reject_master_data_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Master data must be deactivated, not deleted';
END
$$;
CREATE FUNCTION governance.reject_master_data_identity_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME = 'master_data_collections' THEN
        IF OLD.code IS DISTINCT FROM NEW.code THEN
            RAISE EXCEPTION 'Master-data collection codes are immutable';
        END IF;
    ELSIF TG_TABLE_NAME = 'master_data_items' THEN
        IF OLD.collection_code IS DISTINCT FROM NEW.collection_code
           OR OLD.code IS DISTINCT FROM NEW.code THEN
            RAISE EXCEPTION 'Master-data item codes are immutable';
        END IF;
    ELSE
        RAISE EXCEPTION 'Unsupported master-data identity trigger table: %',
            TG_TABLE_NAME;
    END IF;
    RETURN NEW;
END
$$;
SET LOCAL default_tablespace = '';
SET LOCAL default_table_access_method = heap;
CREATE TABLE commercial.agencies (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    external_reference character varying(100) NOT NULL,
    legal_name character varying(200) NOT NULL,
    trading_name character varying(200) NOT NULL,
    website character varying(2048),
    status_collection_code character varying(100) DEFAULT 'lifecycleStatuses'::character varying NOT NULL,
    status_code character varying(100) NOT NULL,
    version bigint NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT ck_agencies_status_collection CHECK (((status_collection_code)::text = 'lifecycleStatuses'::text)),
    CONSTRAINT ck_agencies_version CHECK ((version > 0))
);
ALTER TABLE ONLY commercial.agencies FORCE ROW LEVEL SECURITY;
CREATE TABLE commercial.agent_run_steps (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    step_code character varying(100) NOT NULL,
    agent_code character varying(100) NOT NULL,
    status_collection_code character varying(100) DEFAULT 'lifecycleStatuses'::character varying NOT NULL,
    status_code character varying(100) NOT NULL,
    input_hash character varying(64) NOT NULL,
    output_json jsonb,
    attempt_count integer NOT NULL,
    checkpointed_at_utc timestamp with time zone,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT ck_agent_run_steps_attempts CHECK ((attempt_count >= 0)),
    CONSTRAINT ck_agent_run_steps_hash CHECK (((input_hash)::text ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ck_agent_run_steps_status_collection CHECK (((status_collection_code)::text = 'lifecycleStatuses'::text))
);
CREATE TABLE commercial.agent_runs (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    opportunity_id uuid,
    run_kind_code character varying(100) NOT NULL,
    status_collection_code character varying(100) DEFAULT 'lifecycleStatuses'::character varying NOT NULL,
    status_code character varying(100) NOT NULL,
    input_version bigint NOT NULL,
    requested_by uuid NOT NULL,
    approver_user_id uuid,
    correlation_id uuid NOT NULL,
    current_step_code character varying(100),
    attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at_utc timestamp with time zone,
    lease_owner uuid,
    lease_expires_at_utc timestamp with time zone,
    error_code character varying(100),
    error_detail character varying(1000),
    version bigint NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    completed_at_utc timestamp with time zone,
    campaign_id uuid,
    CONSTRAINT ck_agent_runs_attempts CHECK ((attempts >= 0)),
    CONSTRAINT ck_agent_runs_status_collection CHECK (((status_collection_code)::text = 'lifecycleStatuses'::text)),
    CONSTRAINT ck_agent_runs_version CHECK (((version > 0) AND (input_version > 0))),
    CONSTRAINT ck_agent_runs_work_scope CHECK (((opportunity_id IS NOT NULL) OR (campaign_id IS NOT NULL)))
);
CREATE TABLE commercial.ai_usage_ledger (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    run_id uuid NOT NULL,
    step_id uuid NOT NULL,
    provider_code character varying(100) NOT NULL,
    model_code character varying(300) NOT NULL,
    units integer NOT NULL,
    tool_calls integer NOT NULL,
    incremental_cost_minor bigint NOT NULL,
    cache_status_code character varying(100) NOT NULL,
    recorded_at_utc timestamp with time zone NOT NULL,
    provider_request_id character varying(300),
    CONSTRAINT ck_ai_usage_nonnegative CHECK (((units >= 0) AND (tool_calls >= 0) AND (incremental_cost_minor >= 0))),
    CONSTRAINT ck_ai_usage_provider_shape CHECK (((tool_calls = 0) AND ((((provider_code)::text = 'deterministic'::text) AND ((model_code)::text = 'fixture-v1'::text) AND (units = 0) AND (incremental_cost_minor = 0) AND ((cache_status_code)::text = 'FIXTURE'::text) AND (provider_request_id IS NULL)) OR (((provider_code)::text = 'bedrock'::text) AND ((model_code)::text <> 'fixture-v1'::text) AND (units > 0) AND (incremental_cost_minor >= 0) AND ((cache_status_code)::text = ANY ((ARRAY['LIVE'::character varying, 'CACHE_HIT'::character varying])::text[])) AND (btrim((COALESCE(provider_request_id, ''::character varying))::text) <> ''::text)))))
);
CREATE TABLE commercial.audience_definition_sets (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    brief_version_id uuid NOT NULL,
    version_no integer NOT NULL,
    input_hash character(64) NOT NULL,
    status_collection_code character varying(100) DEFAULT 'lifecycleStatuses'::character varying NOT NULL,
    status_code character varying(100) NOT NULL,
    created_by uuid NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    target_audience_ids_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    targeting_rationale text DEFAULT ''::text NOT NULL,
    positioning_statement text DEFAULT ''::text NOT NULL,
    agent_provider_code character varying(100),
    agent_model_code character varying(300),
    agent_incremental_cost_minor bigint,
    agent_provider_request_id character varying(300),
    CONSTRAINT ck_audience_agent_usage CHECK ((((agent_provider_code IS NULL) AND (agent_model_code IS NULL) AND (agent_incremental_cost_minor IS NULL) AND (agent_provider_request_id IS NULL)) OR commercial.valid_agent_usage_metadata(agent_provider_code, agent_model_code, agent_incremental_cost_minor, agent_provider_request_id))),
