    currency_code character varying(100) NOT NULL,
    vat_status_collection_code character varying(100) DEFAULT 'vatStatuses'::character varying NOT NULL,
    vat_status_code character varying(100) NOT NULL,
    vat_number character varying(50),
    settings_json jsonb NOT NULL,
    version bigint NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    updated_at_utc timestamp with time zone NOT NULL,
    CONSTRAINT ck_tenants_currency_collection CHECK (((currency_collection_code)::text = 'currencies'::text)),
    CONSTRAINT ck_tenants_status_collection CHECK (((status_collection_code)::text = 'lifecycleStatuses'::text)),
    CONSTRAINT ck_tenants_type_collection CHECK (((type_collection_code)::text = 'tenantTypes'::text)),
    CONSTRAINT ck_tenants_vat_collection CHECK (((vat_status_collection_code)::text = 'vatStatuses'::text)),
    CONSTRAINT ck_tenants_version CHECK ((version > 0))
);
ALTER TABLE ONLY commercial.tenants FORCE ROW LEVEL SECURITY;
CREATE TABLE commercial.users (
