CREATE POLICY supplier_claim_invitations_tenant_scope ON commercial.supplier_claim_invitations USING ((tenant_id = commercial.current_tenant_id())) WITH CHECK ((tenant_id = commercial.current_tenant_id()));
ALTER TABLE commercial.supply_coordination ENABLE ROW LEVEL SECURITY;
CREATE POLICY supply_coordination_tenant_scope ON commercial.supply_coordination USING ((tenant_id = commercial.current_tenant_id())) WITH CHECK ((tenant_id = commercial.current_tenant_id()));
CREATE POLICY tenant_scope ON commercial.tenants USING (((id = commercial.current_tenant_id()) OR (EXISTS ( SELECT 1
   FROM commercial.memberships membership
  WHERE ((membership.tenant_id = tenants.id) AND (membership.user_id = commercial.current_user_id())))))) WITH CHECK ((id = commercial.current_tenant_id()));
ALTER TABLE commercial.tenants ENABLE ROW LEVEL SECURITY;
CREATE POLICY user_scope ON commercial.users USING ((id = commercial.current_user_id())) WITH CHECK ((id = commercial.current_user_id()));
ALTER TABLE commercial.users ENABLE ROW LEVEL SECURITY;
